--
-- Table structure for table `chem_elements`
--

DROP TABLE IF EXISTS `chem_elements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chem_elements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `symbol` varchar(8) NOT NULL,
  `name_zh` varchar(32) NOT NULL,
  `name_en` varchar(64) NOT NULL DEFAULT '',
  `atomic_number` int unsigned NOT NULL,
  `atomic_mass` decimal(12,6) DEFAULT NULL,
  `period_no` tinyint unsigned DEFAULT NULL,
  `group_label` varchar(16) DEFAULT NULL,
  `category` varchar(32) DEFAULT NULL COMMENT '金属/非金属/惰性气体等',
  `common_valences` varchar(64) DEFAULT NULL COMMENT '如 +1,-1',
  `atom_structure` text,
  `electron_config` varchar(128) DEFAULT NULL,
  `common_compounds` text,
  `key_properties` text,
  `common_uses` text,
  `status` varchar(32) NOT NULL DEFAULT 'draft',
  `review_note` varchar(255) NOT NULL DEFAULT '',
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `reviewed_by` bigint unsigned DEFAULT NULL,
  `reviewed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chem_element_symbol` (`symbol`),
  UNIQUE KEY `uk_chem_element_atomic_number` (`atomic_number`),
  KEY `idx_chem_element_status` (`status`),
  KEY `idx_chem_element_name` (`name_zh`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

