INSERT INTO `chem_substances` VALUES (1,'钠','Na','金属钠','银白色','固','与水反应','软、密度小于水','强还原性。与O2：常温主要生成Na2O，点燃生成Na2O2；与水、酸剧烈反应放H2；可置换较弱金属离子（题设）。','散热介质、还原剂等（了解）','切割观察光泽','煤油或石蜡油中密封','遇水剧烈，禁止徒手接触水中操作','published','[sub.Na] B3轻改:分条件性质;用途标了解',NULL,NULL,NULL,NULL,'2026-10-18 09:49:45.066','2026-10-18 13:12:15.000'),(2,'水','H2O','水','无色','液','溶剂','无色无味液体','可与活泼金属、氧化物等反应','溶剂、反应物','—','常温密封','常温液体水一般安全；高温蒸汽烫伤风险；按实验室规范使用','published','[sub.H2O] B3轻改:safety表述',NULL,NULL,NULL,NULL,'2026-10-18 09:49:45.066','2026-10-18 13:12:16.000'),(3,'氢氧化钠','NaOH','烧碱,火碱,苛性钠','白色','固','易溶于水放热','白色固体，易潮解，易溶于水放热','强碱。与酸中和；吸收CO2（用量不同可得Na2CO3或NaHCO3）；潮解。','工业制皂、除油','酚酞变红','密封干燥','腐蚀性，禁止直接接触皮肤','published','[sub.NaOH] B3轻改:补潮解与吸收CO2',NULL,NULL,NULL,NULL,'2026-10-18 09:49:45.066','2026-10-18 13:12:15.000'),(4,'氢气','H2','氢气','无色','气','难溶','最轻气体','可燃，还原性','燃料、还原剂','点燃有淡蓝色火焰','钢瓶或发生器','与空气混合遇明火爆炸','published','',NULL,NULL,NULL,NULL,'2026-10-18 09:49:45.066','2026-10-18 09:49:45.066'),(5,'氧化钠','Na2O','氧化钠','白色','固','与水剧烈反应生成 NaOH，不宜简单说“溶于水”','白色固体；碱性氧化物。','与水反应生成氢氧化钠：Na2O+H2O=2NaOH；可与酸反应。氧元素化合价为−2。','高中作碱性氧化物代表物；工业用途了解即可。','与水反应后溶液显碱性，可使酚酞变红。','密封防潮，避免与酸蒸气接触。','与水反应放热，注意防溅。','pending_review','[inv:sub.Na2O] batch3导入 pending_review id=5',2,2,NULL,NULL,'2026-10-18 12:57:53.962','2026-10-18 13:12:06.000'),(6,'过氧化钠','Na2O2','过氧化钠','淡黄色','固','与水剧烈反应，放出氧气','淡黄色固体；过氧化物，氧为−1价。','与水：2Na2O2+2H2O=4NaOH+O2↑；与CO2：2Na2O2+2CO2=2Na2CO3+O2。既可作氧化剂也可在歧化反应中作还原剂。','供氧剂、漂白剂（了解）；呼吸面具相关（了解）。','与水或CO2反应有气泡（O2），余液显碱性。','密封干燥保存，远离有机物与还原性物质。','强氧化性，遇水、酸放热剧烈；禁止与易燃物混放。','pending_review','[inv:sub.Na2O2] batch3导入 pending_review id=6',2,2,NULL,NULL,'2026-10-18 12:57:54.146','2026-10-18 13:12:06.000'),(7,'碳酸钠','Na2CO3','纯碱、苏打','白色','固','易溶于水，水溶液显碱性','白色粉末或结晶；十水合物俗称结晶苏打（了解）。','与酸反应放CO2；可与过量CO2、H2O转化为NaHCO3：Na2CO3+CO2+H2O=2NaHCO3。热稳定性强于NaHCO3。','玻璃、洗涤、制皂等（了解）；实验室制取CO2（与酸）。','加盐酸有气泡，气体使澄清石灰水变浑浊；焰色反应呈黄色（钠）。','密封防潮。','碱性盐，避免长时间接触皮肤与眼睛。','pending_review','[inv:sub.Na2CO3] batch3导入 pending_review id=7',2,2,NULL,NULL,'2026-10-18 12:57:54.336','2026-10-18 13:12:06.000'),(8,'碳酸氢钠','NaHCO3','小苏打','白色','固','可溶于水，水溶液显弱碱性','白色细晶体或粉末。','受热易分解：2NaHCO3=△=Na2CO3+CO2↑+H2O；与酸反应放CO2。与Na2CO3可用加热或酸的用量等区分。','发酵粉、胃酸中和（了解）；灭火器相关了解。','加热有CO2放出；加酸有气泡。','阴凉密封，避免受热分解。','一般较安全，仍避免大量吸入粉尘。','pending_review','[inv:sub.NaHCO3] batch3导入 pending_review id=8',2,2,NULL,NULL,'2026-10-18 12:57:54.482','2026-10-18 13:12:06.000'),(9,'氯化钠','NaCl','食盐','白色','固','易溶于水','白色晶体；熔点较高。','中性盐；熔融或水溶液可导电；一般不与稀酸稀碱发生复分解反应（了解）。','调味、工业制氯碱原料等。','焰色反应黄色；加AgNO3生成白色AgCl沉淀（需结合题设）。','干燥密封。','食用级与试剂级注意区分用途。','pending_review','[inv:sub.NaCl] batch3导入 pending_review id=9',2,2,NULL,NULL,'2026-10-18 12:57:54.652','2026-10-18 13:12:06.000'),(10,'镁','Mg','镁','银白色','固','单质不溶于水；可与酸反应','银白色轻金属；延展性较好。','可在空气中燃烧发出耀眼白光生成MgO；能与酸反应放H2；点燃时可在CO2中继续燃烧：2Mg+CO2=2MgO+C。','合金、烟火、还原剂（了解）。','燃烧白光；与酸反应放H2。','干燥保存；粉状镁注意防火。','燃烧强光伤眼；粉尘有燃烧爆炸风险。','pending_review','[inv:sub.Mg] batch3导入 pending_review id=10',2,2,NULL,NULL,'2026-10-18 12:57:54.827','2026-10-18 13:12:06.000'),(11,'氧化镁','MgO','氧化镁、苦土（了解）','白色','固','难溶于水；可与酸反应','白色粉末；熔点高，可作耐火材料（了解）。','碱性氧化物；与酸反应生成镁盐和水；与水反应缓慢生成Mg(OH)2（了解）。','耐火材料、医药等（了解）。','溶于酸；结合镁的来源反应推断。','干燥密封。','粉尘刺激呼吸道。','pending_review','[inv:sub.MgO] batch3导入 pending_review id=11',2,2,NULL,NULL,'2026-10-18 12:57:54.981','2026-10-18 13:12:07.000'),(12,'氢氧化镁','Mg(OH)2','氢氧化镁','白色','固','难溶于水，属中强碱沉淀','白色固体（沉淀）。','能与酸反应；碱性弱于NaOH、KOH；不溶于过量NaOH（与Al(OH)3对比）。','抗酸药等（了解）。','白色沉淀，溶于酸，不溶于强碱。','密封。','一般刺激性较小。','pending_review','[inv:sub.MgOH2] batch3导入 pending_review id=12',2,2,NULL,NULL,'2026-10-18 12:57:55.152','2026-10-18 13:12:07.000'),(13,'铝','Al','铝','银白色','固','单质不溶于水；可与酸、强碱溶液反应','银白色轻金属；延展性好；导热导电性较好。','表面易生成致密Al2O3氧化膜；可与酸放H2；也可与NaOH溶液反应：2Al+2NaOH+2H2O=2NaAlO2+3H2↑（溶液中常写[Al(OH)4]-，了解）。','建筑、电线、包装、合金。','与酸、碱均能反应放H2（两性金属特征之一）。','常温较稳定；避免强酸强碱长期腐蚀。','铝粉易燃；与汞盐等反应破坏氧化膜（了解，勿操作）。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:sub.Al] batch3导入 pending_review id=13',2,2,NULL,NULL,'2026-10-18 12:57:55.305','2026-10-18 20:46:35.475'),(14,'氧化铝','Al2O3','氧化铝、铝氧','白色','固','难溶于水；可溶于强酸与强碱','白色固体；熔点高；刚玉等为天然形态（了解）。','两性氧化物：Al2O3+6HCl=2AlCl3+3H2O；Al2O3+2NaOH=2NaAlO2+H2O（简化写法；[Al(OH)4]-口径了解/待核实）。','冶炼铝原料、耐火/陶瓷材料（了解）。','既能溶于强酸又能溶于强碱。','干燥保存。','粉尘注意防护。','pending_review','[inv:sub.Al2O3] 待核实:与碱产物写法',2,2,NULL,NULL,'2026-10-18 12:57:55.477','2026-10-18 13:12:07.000'),(15,'氢氧化铝','Al(OH)3','氢氧化铝','白色','固','难溶于水；可溶于强酸与强碱','白色胶状沉淀。','两性氢氧化物：Al(OH)3+3HCl=AlCl3+3H2O；Al(OH)3+NaOH=NaAlO2+2H2O（简化写法；[Al(OH)4]-了解/待核实）。受热可分解为Al2O3（了解）。','抗酸药、净水等（了解）。','白色沉淀，酸碱均可溶。','湿存或按试剂要求密封。','一般刺激性较小。','pending_review','[inv:sub.AlOH3] 待核实:与碱产物写法',2,2,NULL,NULL,'2026-10-18 12:57:55.631','2026-10-18 13:12:07.000'),(16,'铁','Fe','铁','银白色（粉末可呈灰黑）','固','单质不溶于水；可与稀酸反应','银白色金属；具铁磁性；较活泼。','与O2点燃生成Fe3O4；与稀H2SO4/HCl生成Fe2+盐与H2；可置换活动性较弱的金属离子（如Cu2+）。潮湿空气中易生锈。','结构材料、合金基础。','与酸放H2；置换CuSO4得红色Cu。','干燥防锈；粉末防火。','细铁粉易燃；铁锈实验注意环境。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:sub.Fe] batch3导入 pending_review id=16',2,2,NULL,NULL,'2026-10-18 12:57:55.831','2026-10-18 20:46:35.476'),(17,'氧化铁','Fe2O3','氧化铁、铁红','红棕色','固','难溶于水；可与酸反应','红棕色粉末。','Fe为+3价；可被CO等高还原：Fe2O3+3CO=高温=2Fe+3CO2。可与酸生成铁盐。','颜料、炼铁原料（赤铁矿主要成分，了解）。','红棕色；溶于酸得Fe3+溶液（黄/棕黄）。','干燥。','粉尘防护。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:sub.Fe2O3] batch3导入 pending_review id=17',2,2,NULL,NULL,'2026-10-18 12:57:56.002','2026-10-18 20:46:35.476'),(18,'四氧化三铁','Fe3O4','磁性氧化铁、磁石成分（了解）','黑色','固','难溶于水','黑色固体；具磁性。','可看作FeO·Fe2O3（了解）；铁在氧气中点燃的产物。与酸反应较复杂，高中以认识为主。','磁性材料等（了解）。','黑色；可被磁铁吸引（结合样品）。','干燥。','粉尘防护。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:sub.Fe3O4] batch3导入 pending_review id=18',2,2,NULL,NULL,'2026-10-18 12:57:56.219','2026-10-18 20:46:35.476'),(19,'氢氧化铁','Fe(OH)3','氢氧化铁','红褐色','固','难溶于水','红褐色沉淀。','由Fe3+与碱生成；可溶于酸。Fe(OH)2在空气中氧化最终可得红褐色Fe(OH)3。受热分解为Fe2O3（了解）。','净水、颜料相关（了解）。','红褐色沉淀；溶于酸得Fe3+。','湿存沉淀或按试剂要求。','一般按实验室规范操作。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:sub.FeOH3] batch3导入 pendin