/*!40000 ALTER TABLE `chem_reactions` DISABLE KEYS */;
INSERT INTO `chem_reactions` VALUES (1,'钠与水反应','2Na+2H2O=2NaOH+H2','2Na + 2H2O = 2NaOH + H2↑','2Na + 2H2O = 2Na+ + 2OH- + H2↑','常温','钠浮于水面、熔化成小球、四处游动、发出嘶嘶声，滴酚酞变红；产生可燃气体','钠失电子被氧化，水中氢得电子被还原','H2O','Na','NaOH','H2','Na 失 1e-；H 得 1e-（按原子计）',2,5,1,'equation_write,balance,redox,property,phenomenon,conversion','published','',NULL,NULL,NULL,NULL,'2026-10-18 09:49:45.300','2026-10-18 12:04:18.879'),(2,'钠常温与氧气','4Na+O2=2Na2O','4Na + O2 = 2Na2O',NULL,'常温（表面生成）','钠表面变暗，生成一层氧化物。','钠还原性强，常温即可被氧气缓慢氧化，主要生成氧化钠。化合反应中氧化产物与还原产物均为Na2O（训练须说明）。','O2','Na','Na2O','Na2O','Na 失 1e-；O 得 2e-（按原子计，配平后守恒）',2,4,0,'equation.write_from_text,equation.balance,redox.identify','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.4Na_O2] canonical=4Na+O2=2Na2O; batch3导入 pending_review id=2',2,2,NULL,NULL,'2026-10-18 12:58:24.574','2026-10-18 20:46:35.479'),(3,'钠加热与氧气','2Na+O2=Na2O2','2Na + O2 = Na2O2',NULL,'加热点燃（燃烧）','剧烈燃烧，火焰黄色，生成淡黄色固体。','钠在空气或氧气中燃烧生成过氧化钠。化合反应中氧化产物与还原产物均为Na2O2（训练须说明）。','O2','Na','Na2O2','Na2O2','Na 失 1e-；O 得 1e-（过氧化物中O为−1价，按原子计）',2,5,0,'equation.write_from_text,equation.balance,redox.identify','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.2Na_O2_heat] canonical=2Na+O2=Na2O2; batch3导入 pending_review id=3',2,2,NULL,NULL,'2026-10-18 12:58:24.949','2026-10-18 20:46:35.479'),(4,'过氧化钠与水','2Na2O2+2H2O=4NaOH+O2','2Na2O2 + 2H2O = 4NaOH + O2↑','2Na2O2 + 2H2O = 4Na+ + 4OH- + O2↑','常温','剧烈反应，放热，产生气泡；溶液显碱性。','过氧化钠中氧−1价发生歧化：一部分升为0价（O2），一部分降为−2价（OH-）。','Na2O2','Na2O2','O2','NaOH','部分O(−1)失e-→O2；部分O(−1)得e-→OH-（歧化）',3,5,0,'equation.write_from_text,equation.balance,redox.identify','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.2Na2O2_2H2O] canonical=2Na2O2+2H2O=4NaOH+O2; batch3导入 pending_review id=4',2,2,NULL,NULL,'2026-10-18 12:58:25.190','2026-10-18 20:46:35.479'),(5,'过氧化钠与二氧化碳','2Na2O2+2CO2=2Na2CO3+O2','2Na2O2 + 2CO2 = 2Na2CO3 + O2↑',NULL,'常温','吸收CO2并放出O2；固体由淡黄色转变为白色（碳酸钠）。','过氧化钠与CO2反应供氧，氧元素歧化。','Na2O2','Na2O2','O2','Na2CO3','部分O(−1)失e-→O2；部分O(−1)得e-→碳酸根中O(−2)（歧化）',3,5,0,'equation.write_from_text,equation.balance,redox.identify','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.2Na2O2_2CO2] canonical=2Na2O2+2CO2=2Na2CO3+O2; batch3导入 pending_review id=5',2,2,NULL,NULL,'2026-10-18 12:58:25.479','2026-10-18 20:46:35.480'),(6,'氧化钠与水','Na2O+H2O=2NaOH','Na2O + H2O = 2NaOH','Na2O + H2O = 2Na+ + 2OH-','常温','剧烈放热，生成强碱溶液。','碱性氧化物与水反应生成碱；化合价不变，非氧化还原。',NULL,NULL,NULL,NULL,NULL,1,4,0,'equation.write_from_text,equation.balance','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.Na2O_H2O] canonical=Na2O+H2O=2NaOH; batch3导入 pending_review id=6',2,2,NULL,NULL,'2026-10-18 12:58:25.816','2026-10-18 20:46:35.480'),(7,'氢氧化钠与二氧化碳','2NaOH+CO2=Na2CO3+H2O','2NaOH + CO2 = Na2CO3 + H2O','2OH- + CO2 = CO32- + H2O','本条主方程式对应n(NaOH):n(CO2)=2:1（碱足量或CO2适量）生成Na2CO3。若继续通入过量CO2，可进一步：Na2CO3+CO2+H2O=2NaHCO3（见rxn.Na2CO3_CO2_H2O）。教材对“过量”措辞待核实，命题须写明用量条件。','气体被吸收；无明显特殊颜色变化。','酸性氧化物与碱反应；产物随相对用量变化，不可脱离用量谈唯一产物。',NULL,NULL,NULL,NULL,NULL,2,5,0,'equation.write_from_text,equation.balance','pending_review','[inv:rxn.NaOH_CO2] 待核实:教材过量措辞;已写清用量分支',2,2,NULL,NULL,'2026-10-18 12:58:26.074','2026-10-18 13:12:09.000'),(8,'氢氧化钠与盐酸','NaOH+HCl=NaCl+H2O','NaOH + HCl = NaCl + H2O','OH- + H+ = H2O','常温，溶液中进行','放热；酸碱中和，指示剂可变色。','强酸强碱中和生成盐和水；非氧化还原。',NULL,NULL,NULL,NULL,NULL,1,5,0,'equation.write_from_text,equation.balance,ion.ionic_eq','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.NaOH_HCl] canonical=NaOH+HCl=NaCl+H2O; batch3导入 pending_review id=8',2,2,NULL,NULL,'2026-10-18 12:58:26.353','2026-10-18 20:46:35.480'),(9,'碳酸氢钠受热分解','2NaHCO3=Na2CO3+CO2+H2O','2NaHCO3 =△= Na2CO3 + CO2↑ + H2O',NULL,'加热','固体质量减少，产生使澄清石灰水变浑浊的气体。','碳酸氢钠热稳定性较差，分解生成碳酸钠、二氧化碳和水；非氧化还原。',NULL,NULL,NULL,NULL,NULL,2,5,0,'equation.write_from_text,equation.balance','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.NaHCO3_heat] canonical=2NaHCO3=Na2CO3+CO2+H2O; batch3导入 pending_review id=9',2,2,NULL,NULL,'2026-10-18 12:58:26.649','2026-10-18 20:46:35.481'),(10,'碳酸钠与盐酸','Na2CO3+2HCl=2NaCl+CO2+H2O','Na2CO3 + 2HCl = 2NaCl + CO2↑ + H2O','CO32- + 2H+ = CO2↑ + H2O','常温，酸足量','产生气泡；气体使澄清石灰水变浑浊。','碳酸盐与强酸反应放出CO2；非氧化还原。',NULL,NULL,NULL,NULL,NULL,1,5,0,'equation.write_from_text,equation.balance,ion.ionic_eq','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.Na2CO3_2HCl] canonical=Na2CO3+2HCl=2NaCl+CO2+H2O; batch3导入 pending_review id=10',2,2,NULL,NULL,'2026-10-18 12:58:26.860','2026-10-18 20:46:35.481'),(11,'镁与氧气','2Mg+O2=2MgO','2Mg + O2 =点燃= 2MgO',NULL,'点燃','发出耀眼白光，生成白色固体。','镁被氧气氧化生成氧化镁。','O2','Mg','MgO','MgO','Mg 失 2e-；O 得 2e-（按原子计）',1,4,0,'equation.write_from_text,equation.balance,redox.identify','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.2Mg_O2] canonical=2Mg+O2=2MgO; batch3导入 pending_review id=11',2,2,NULL,NULL,'2026-10-18 12:58:27.227','2026-10-18 20:46:35.481'),(12,'镁与盐酸','Mg+2HCl=MgCl2+H2','Mg + 2HCl = MgCl2 + H2↑','Mg + 2H+ = Mg2+ + H2↑','常温，稀盐酸','镁溶解，产生气泡；溶液温度升高。','活泼金属与酸反应生成盐和氢气。','HCl','Mg','MgCl2','H2','Mg 失 2e-；H 得 1e-（按原子计）',1,4,0,'equation.write_from_text,equation.balance,redox.identify','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.Mg_2HCl] canonical=Mg+2HCl=MgCl2+H2; batch3导入 pending_review id=12',2,2,NULL,NULL,'2026-10-18 12:58:27.664','2026-10-18 20:46:35.481'),(13,'镁与二氧化碳','2Mg+CO2=2MgO+C','2Mg + CO2 =点燃= 2MgO + C',NULL,'点燃（镁条在CO2中继续燃烧）','继续燃烧，瓶壁有白色MgO，并出现黑色碳。','镁还原性强，可夺取CO2中的氧，生成MgO与C。','CO2','Mg','MgO','C','Mg 失 2e-；C(+4)得e-→C(0)',3,4,0,'equation.write_from_text,equation.balance,redox.identify','pending_review','[inv:rxn.Mg_CO2] canonical=2Mg+CO2=2MgO+C; batch3导入 pending_review id=13',2,2,NULL,NULL,'2026-10-18 12:58:27.973','2026-10-18 13:12:10.000'),(14,'铝与氧气','4Al+3O2=2Al2O3','4Al + 3O2 =点燃= 2Al2O3',NULL,'本条方程式对应点燃或高温燃烧条件。另：常温下铝表面可缓慢生成致密Al2O3氧化膜（化学式相同，但不属于本条“点燃燃烧”现象，训练时须分条件命题）。','点燃/高温：剧烈燃烧，生成白色固体Al2O3。常温：表面缓慢形成致密氧化膜保护内部铝（观察不到剧烈燃烧）。','铝被氧气氧化生成氧化铝；化合反应中氧化产物与还原产物均为Al2O3。','O2','Al','Al2O3','Al2O3','Al 失 3e-；O 得 2e-（按原子计，配平后守恒）',2,4,0,'equation.write_from_text,equation.balance,redox.identify','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.4Al_3O2] B3整改:分条件写点燃燃烧与常温成膜',2,2,NULL,NULL,'2026-10-18 12:58:28.294','2026-10-18 20:46:35.482'),(15,'铝与盐酸','2Al+6HCl=2AlCl3+3H2','2Al + 6HCl = 2AlCl3 + 3H2↑','2Al + 6H+ = 2Al3+ + 3H2↑','常温，稀盐酸（氧化膜除去后更明显）','铝溶解，产生气泡。','铝与强酸反应生成铝盐和氢气。','HCl','Al','AlCl3','H2','Al 失 3e-；H 得 1e-（按原子计）',2,4,0,'equation.write_from_text,equation.balance,redox.identify','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.2Al_6HCl] canonical=2Al+6HCl=2AlCl3+3H2; batch3导入 pending_review id=15',2,2,NULL,NULL,'2026-10-18 12:58:28.553','2026-10-18 20:46:35.482'),(16,'铝与氢氧化钠溶液','2Al+2NaOH+2H2O=2NaAlO2+3H2','2Al + 2NaOH + 2H2O = 2NaAlO2 + 3H2↑','2Al + 2OH- + 2H2O = 2AlO2- + 3H2↑','常温或加热，NaOH溶液。书写口径：本库默认高中简化式NaAlO2/AlO2-；水溶液中亦常见[Al(OH)4]-（了解，待教材核实统一）。','铝溶解，产生气泡；溶液中生成偏铝酸盐。','铝与强碱溶液反应放氢气。氧化剂为H2O（H得电子），还原剂为Al。产物写法见conditions。','H2O','Al','NaAlO2','H2','Al 失 3e-；H(+1)得e-→H2',3,5,0,'equation.write_from_text,equation.balance,redox.identify','pending_review','[inv:rxn.2Al_2NaOH] 待核实:AlO2-与[Al(OH)4]-教材口径;命题须指定写法',2,2,NULL,NULL,'2026-10-18 12:58:28.854','2026-10-18 13:12:10.000'),(17,'氧化铝与盐酸','Al2O3+6HCl=2AlCl3+3H2O','Al2O3 + 6HCl = 2AlCl3 + 3H2O','Al2O3 + 6H+ = 2Al3+ + 3H2O','常温或加热','固体逐渐溶解。','两性氧化物与强酸反应生成铝盐和水；非氧化还原。',NULL,NULL,NULL,NULL,NULL,2,5,0,'equation.write_from_text,equation.balance','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:rxn.Al2O3_6HCl] canonical=Al2O3+6HCl=2AlCl3+3H2O; batch3导入 pending_review id=17',2,2,NULL,NULL,'2026-10-18 12:58:29.186','2026-10-18 20:46:35.482'),(18,'氧化铝与氢氧化钠','Al2O3+2NaOH=2NaAlO2+H2O','Al2O3 + 2NaOH = 2NaAlO2 + H2O','Al2O3 + 2OH- = 2AlO2- + H2O','常温或加热，NaOH溶液。本库默认简化式NaAlO2/AlO2-；亦有教材写Na[Al(OH)4]/[Al(OH)4]-（待核实，命题须指