INSERT INTO `chem_experiments` VALUES (1,'钠与水的反应','property','观察钠与水反应的现象并验证产物','钠与水发生置换反应生成氢氧化钠和氢气','烧杯、镊子、小刀、玻璃片、滤纸、酚酞、火柴','金属钠、水、酚酞','1.用镊子取绿豆大钠，滤纸吸干煤油；2.放入盛水烧杯；3.滴入酚酞；4.收集气体点燃检验','浮、熔、游、响，溶液变红，气体可燃','产物为 NaOH 与 H2，反应放热','钠取用量要小；用镊子操作；不可用手直接接触','钠遇水剧烈放热，可能溅射；禁止在家自行操作',1,'危险实验请在实验室由教师指导下完成，禁止在家自行操作。','published','',NULL,NULL,NULL,NULL,'2026-10-18 09:49:45.725','2026-10-18 09:49:45.725'),(2,'钠在空气中燃烧','property','观察钠在空气或氧气中燃烧的现象，认识燃烧产物为过氧化钠。','钠加热燃烧与氧气反应：2Na+O2=点燃=Na2O2，生成淡黄色固体。','坩埚或燃烧匙、酒精灯、坩埚钳、石棉网、玻璃片等','金属钠、空气或氧气','1.取绿豆大钠块，用滤纸吸干煤油，切去氧化层；2.放于燃烧匙或坩埚中加热至燃烧；3.观察火焰颜色与产物颜色；4.冷却后妥善处理残渣。','剧烈燃烧，火焰黄色，生成淡黄色固体。','钠在空气中燃烧生成过氧化钠（淡黄色），不同于常温表面主要生成氧化钠。','钠用量宜小；远离面部；残钠按教师指导处理，不可直接扔进废液缸。','钠遇水剧烈反应，必须吸干煤油；燃烧强光与飞溅注意防护。',1,'危险实验请在实验室由教师指导下完成，禁止在家自行操作。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.Na_O2] batch3导入 pending_review id=2',2,2,NULL,NULL,'2026-10-18 12:59:02.674','2026-10-18 20:46:35.487'),(3,'过氧化钠与水/二氧化碳','property','验证过氧化钠与水、二氧化碳反应并放出氧气。','2Na2O2+2H2O=4NaOH+O2↑；2Na2O2+2CO2=2Na2CO3+O2。可用带火星木条检验O2，酚酞检验碱。','试管、导管、酒精灯（如需）、木条、胶头滴管等','过氧化钠、水、二氧化碳（或呼出气体）、酚酞、带火星木条','1.向盛少量Na2O2的试管加水，观察；2.用带火星木条检验气体；3.取溶液滴酚酞；4.另取Na2O2通入CO2，检验是否放O2。','加水：放热、有气泡，带火星木条复燃；取溶液滴酚酞变红。通CO2：有气泡放出，带火星木条可复燃（与水实验分步观察，勿混为同一步现象）。','过氧化钠与水或CO2反应都放出氧气，体现其供氧与碱性产物特征。','Na2O2用量少；加水缓慢；勿用手直接接触。','强氧化剂，腐蚀性，禁止与有机物随意混合。',1,'危险实验请在实验室由教师指导下完成，禁止在家自行操作。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.Na2O2_H2O] batch3导入 pending_review id=3',2,2,NULL,NULL,'2026-10-18 12:59:02.823','2026-10-18 20:46:35.488'),(4,'铝及氧化铝两性验证','property','验证铝能与强酸、强碱反应；验证Al2O3、Al(OH)3的两性（酸碱均可溶）。','区分两类：①单质Al与强酸/强碱反应放H2；②Al2O3、Al(OH)3为两性氧化物/氢氧化物，可与强酸、强碱反应。Al(OH)3沉淀在酸或过量强碱中溶解是两性关键实验现象。','试管、胶头滴管、药匙等','铝片或铝粉、Al2O3、AlCl3溶液、NaOH溶液、盐酸、氨水等','1.铝分别与盐酸、NaOH反应，观察放H2；2.用Al3+加氨水制Al(OH)3，分两份分别加盐酸与NaOH，观察沉淀溶解；3.氧化铝分别溶于酸、碱（可微热）。','铝与酸碱均有气泡；氢氧化铝白色沉淀加酸或过量碱均溶解。','铝单质可与强酸、强碱反应；氧化铝、氢氧化铝具有两性。','NaOH腐蚀性强；铝粉反应较快注意控制用量。','强酸强碱防护；氢气实验远离明火。',1,'危险实验请在实验室由教师指导下完成，禁止在家自行操作。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.Al_amphoteric] batch3导入 pending_review id=4',2,2,NULL,NULL,'2026-10-18 12:59:02.902','2026-10-18 20:46:35.488'),(5,'铁生锈条件探究','inquiry','探究铁生锈与水和氧气的关系。','铁在潮湿空气中易锈蚀，需要O2与H2O共同作用（高中定性结论）。','试管、橡皮塞、棉花等','洁净铁钉、水、食盐水（可选）、干燥剂（如无水CaCl2，了解）','1.设置对照：①干燥空气中的铁钉；②浸没煮沸冷却蒸馏水并油封隔绝空气；③部分浸入水中接触空气；2.放置数日观察锈蚀情况。','既接触水又接触空气的铁钉最易生锈；干燥或隔绝空气者不易生锈。','铁生锈通常需要水和氧气同时存在。','铁钉表面除油污；对照实验条件控制单一变量。','一般危险性较低，仍按实验室规则操作。',0,'建议在教师指导下进行对照实验；家庭仅可做无危险观察，勿使用不明化学品。','pending_review','[inv:exp.Fe_rust] batch3导入 pending_review id=5',2,2,NULL,NULL,'2026-10-18 12:59:02.995','2026-10-18 13:12:13.000'),(6,'金属活动性顺序实验','property','通过金属与酸、盐溶液反应比较金属活动性强弱。','活动性强的金属更易与酸反应放H2，并能从活动性较弱金属的盐溶液中置换出该金属。','试管、砂纸、胶头滴管等','Mg、Zn、Fe、Cu等金属；稀盐酸或稀硫酸；CuSO4、AgNO3等盐溶液（按教材）','1.比较不同金属与同浓度稀酸反应快慢与是否反应；2.将较活泼金属插入CuSO4等溶液观察置换；3.归纳活动性顺序。','反应剧烈程度不同；有的金属表面析出红色铜等。','可得出如 Mg>Zn>Fe>Cu 等活动性顺序片段（以课本完整顺序为准）。','酸浓度不宜过高；AgNO3等有毒试剂规范使用。','酸腐蚀；含重金属盐废液回收，禁止倾倒。',1,'危险实验请在实验室由教师指导下完成，禁止在家自行操作。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.metal_activity] batch3导入 pending_review id=6',2,2,NULL,NULL,'2026-10-18 12:59:03.062','2026-10-18 20:46:35.488'),(7,'氢气还原氧化铜','property','验证氢气的还原性，观察氧化铜被还原为铜。','CuO+H2=△=Cu+H2O；操作顺序强调防爆炸：先通H2排尽空气再加热，冷却后停H2。','硬质玻璃管、酒精灯、导管、氢气发生装置、铁架台等','氧化铜、锌粒与稀硫酸（制H2）或氢气钢瓶（教师）、干燥剂等','1.检查装置气密性；2.通H2验纯；3.通H2片刻后加热CuO；4.观察变色与水珠；5.停止加热后继续通H2至冷却。','黑色CuO变为紫红色Cu，管口有水珠。','氢气在加热条件下能还原氧化铜。','必须验纯；严禁先加热后通H2；尾气处理按教师要求。','氢气易燃易爆；全过程教师指导，学生不得擅自操作气源。',1,'危险实验请在实验室由教师指导下完成，禁止在家自行操作。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.CuO_H2_reduce] batch3导入 pending_review id=7',2,2,NULL,NULL,'2026-10-18 12:59:03.203','2026-10-18 20:46:35.489'),(8,'Fe3+与KSCN的检验','test','学习用KSCN检验Fe3+，观察血红色现象；并对比Fe2+氧化后的检验。','Fe3+与SCN-反应生成血红色物质（高中写Fe(SCN)3或络离子了解即可）。','试管、胶头滴管等','FeCl3溶液、FeSO4溶液、KSCN溶液、氯水或H2O2（氧化Fe2+，按教材）','1.向FeCl3溶液滴加KSCN，观察血红色；2.向FeSO4溶液滴加KSCN，无明显血红色；3.再加入氯水等氧化剂后滴KSCN，出现血红色。','Fe3+遇KSCN呈血红色；Fe2+需氧化为Fe3+后才显血红色。','KSCN可用于检验Fe3+；检验Fe2+时常先氧化再检验。','试剂用量少；氯水在通风处使用。','氯水刺激性；铁盐废液按规范回收。',1,'危险实验请在实验室由教师指导下完成，禁止在家自行操作。','pending_review','[inv:exp.Fe3_SCN] 增补；血红色现象; batch3导入 pending_review id=8 待核实:教材现象口径;非默认核心训练;excludeDefaultUntilVerified',2,2,NULL,NULL,'2026-10-18 12:59:03.392','2026-10-18 19:27:38.803'),(9,'氯气的实验室制法','gas_prep','学习用MnO2与浓盐酸加热制取氯气，并认识收集与尾气处理。','MnO2+4HCl(浓)=△=MnCl2+Cl2↑+2H2O；Cl2密度比空气大，可用向上排空气法；尾气用NaOH吸收。','圆底烧瓶、分液漏斗、酒精灯、导管、集气瓶、尾气吸收装置等','MnO2、浓盐酸、NaOH溶液（尾气）','1.检查气密性；2.加入MnO2，分液漏斗加浓盐酸，加热；3.向上排空气法收集；4.多余Cl2用NaOH吸收；5.规范处理残液。','产生黄绿色气体；集气瓶逐渐呈黄绿色。','可用MnO2与浓盐酸加热制Cl2；必须处理尾气。','浓盐酸过量与加热控制；全通风；尾气吸收不可缺失。','Cl2有毒；禁止家用；必须在通风橱由教师指导完成。',1,'危险气体实验禁止在家操作。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.Cl2_prep] 危险气体实验禁止家用; batch4导入 pending_review id=9',2,2,NULL,NULL,'2026-10-18 13:26:32.024','2026-10-18 20:46:35.601'),(10,'氯气性质实验','property','观察氯气氧化性、与水/碱反应及漂白相关现象（教师演示为主）。','Cl2具强氧化性；Cl2+H2O⇌HCl+HClO；Cl2+2NaOH=NaCl+NaClO+H2O；湿润氯气漂白实质为HClO。','集气瓶、胶头滴管、有色布条、试管等','氯气、水、NaOH溶液、干燥/湿润有色布条、淀粉KI试纸等','1.对比干燥与湿润有色布条在Cl2中的现象；2.氯水滴加指示剂或观察颜色；3.Cl2通入NaOH观察气体吸收；4.湿润淀粉KI试纸检验（按教材）。','湿润布条褪色、干燥布条通常不褪色（或褪色不明显）；氯水浅黄绿；通入碱液气体被吸收；淀粉KI试纸变蓝。','氯气氧化性强；漂白与HClO相关；可与碱反应。','用量少；通风；区分现象与结论。','有毒气体；禁止家用。',1,'危险气体实验禁止在家操作。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.Cl2_property] 危险气体实验禁止家用; batch4导入 pending_review id=10',2,2,NULL,NULL,'2026-10-18 13:26:32.136','2026-10-18 20:46:35.602'),(11,'氯化氢/盐酸相关实验','gas_prep','认识HCl气体的制取思路、溶解性及与氨的白烟检验（按教材选取）。','浓硫酸与氯化钠加热可制HCl（了解）；HCl极易溶于水得盐酸；NH3+HCl=NH4Cl产生白烟。','发生装置、导管、集气瓶或检验用品等','NaCl、浓硫酸（若制取）、浓氨水、蒸馏水、指示剂等','1.若做白烟检验：浓盐酸与浓氨水靠近观察白烟；2.盐酸性质：石蕊变红、与活泼金属等（按教材）；3.注意防倒吸与腐蚀。','白烟；盐酸使石蕊变红；与活泼金属有气泡等。','HCl与NH3可生成NH4Cl；盐酸具强酸通性。','浓酸腐蚀；气体实验防倒吸。','刺激性/腐蚀性；禁止家用危险操作。',1,'危险实验禁止在家操作。','pending_review','[inv:exp.HCl_prep] 危险气体实验禁止家用; batch4导入 pending_review id=11',2,2,NULL,NULL,'2026-10-18 13:26:32.227','2026-10-18 13:44:47.000'),(12,'二氧化硫漂白与还原性','property','观察SO2使品红褪色及加热恢复，并认识其还原性表现（与Cl2漂白对比）。','SO2漂白：与有色物质生成不稳定无色物质，加热可恢复。还原性：可使某些氧化剂褪色（如酸性KMnO4，了解/题设）。与HClO漂白不可逆不同。','试管、导管、酒精灯、品红溶液等','SO2（现制或通入）、品红溶液、酸性KMnO4（可选了解）','1.SO2通入品红，观察褪色；2.加热褪色后的溶液，观察是否恢复；3.可选：通入酸性KMnO4观察褪色（了解）；4.尾气吸收处理。','品红褪色；加热后红色可恢复；KMnO4可褪色（若做）。','SO2具漂白性（可逆恢复）和还原性；与次氯酸漂白不同。','SO2有毒，通风；尾气处理。','有毒气体；禁止家用。',1,'危险气体实验禁止在家操作。','pending_review','[inv:exp.SO2_property] 危险气体实验禁止家用; batch4导入 pending_review id=12',2,2,NULL,NULL,'2026-10-18 13:26:32.475','2026-10-18 13:44:48.000'),(13,'氨的实验室制法与喷泉','gas_prep','学习铵盐与碱共热制氨，并认识氨极易溶于水的喷泉实验原理。','NH4Cl+NaOH=△=NaCl+NH3↑+H2O；氨密度比空气小，向下排空气法收集；喷泉体现极易溶于水且水溶液显碱性。','大试管、酒精灯、导管、圆底烧瓶、胶头滴管、水槽等','NH4Cl、Ca(OH)2或NaOH、酚酞、水','1.铵盐与碱混匀加热制NH3；2.向下排空气法收集；3.湿润红色石蕊试纸检验；4.喷泉：烧瓶充满NH3，滴管挤入水，打开止水夹形成喷泉，酚酞变红。','刺激性气味；石蕊试纸变蓝；喷泉，溶液变红。','可用铵盐与碱制NH3；氨极易溶于水，水溶液显碱性。','防倒吸；加热均匀；收集方法正确。','刺激性气体；教师指导；禁止家用。',1,'危险实验禁止在家操作。','pending_review','[inv:exp.NH3_prep] 危险气体实验禁止家用; batch4导入 pending_review id=13',2,2,NULL,NULL,'2026-10-18 13:26:32.636','2026-10-18 13:44:49.000'),(14,'硝酸与铜反应对比','property','对比稀硝酸与浓硝酸和铜反应的产物气体差异（教师演示）。','稀：3Cu+8HNO3=3Cu(NO3)2+2NO↑+4H2O；浓：Cu+4HNO3=Cu(NO3)2+2NO2↑+2H2O。条件不同产物不同。','试管、导管、通风橱等','铜片、稀硝酸、浓硝酸','1.通风橱中分别进行稀/浓硝酸与铜反应；2.观察气体颜色与溶液颜色；3.稀硝酸产生的NO遇空气变红棕；4.规范处理废液尾气。','稀硝酸：无色气体遇空气变红棕，溶液变蓝；浓硝酸：立即大量红棕色气体，溶液变蓝。','浓稀硝酸氧化产物气态氮氧化物不同，必须分条件书写。','氮氧化物有毒；用量少；通风。','强腐蚀与有毒气体；禁止家用。',1,'危险实验禁止在家操作。','pending_review','[inv:exp.HNO3_Cu] 危险气体实验禁止家用; batch4导入 pending_review id=14',2,2,NULL,NULL,'2026-10-18 13:26:32.737','2026-10-18 13:44:50.000'),(15,'二氧化碳性质与检验','property','检验CO2并使澄清石灰水变浑浊，认识不支持燃烧等性质（镁等例外另述）。','CO2+Ca(OH)2=CaCO3↓+H2O；一般不燃烧也不支持燃烧（镁等例外见金属章）。','集气瓶、导管、火柴、澄清石灰水等','CO2（大理石与稀盐酸制取）、澄清石灰水','1.制取并收集CO2；2.通入澄清石灰水观察浑浊；3.燃烧着的木条伸入集气瓶观察熄灭；4.与SO2区分时结合漂白等题设。','石灰水变浑浊；木条熄灭。','可用澄清石灰水检验CO2；一般不支持燃烧。','制取防倒吸；废液处理。','高浓度窒息；实验室规范操作。',0,'建议在教师指导下完成；勿使用不明化学品。','pending_review','[inv:exp.CO2_property] 危险气体实验禁止家用; batch4导入 pending_review id=15',2,2,NULL,NULL,'2026-10-18 13:26:32.852','2026-10-18 13:44:51.000'),(16,'二氧化硅与玻璃仪器腐蚀警示','safety','认识玻璃含SiO2，热的强碱溶液可腐蚀玻璃，强化仪器使用安全。','SiO2+2NaOH=Na2SiO3+H2O；长期盛放碱液会腐蚀玻璃磨口等。','玻璃仪器（展示说明为主）','NaOH溶液（教师说明，不必真实长时间腐蚀演示）','1.讲解玻璃成分含SiO2；2.写出与NaOH反应方程式；3.强调碱液不宜长期存放于玻璃试剂瓶磨口；4.讨论塑料瓶等替代（了解）。','本实验以讲解警示为主；若观察长期存放碱液的瓶塞黏结等现象按实物说明。','SiO2显酸性氧化物性质；使用强碱需注意保护玻璃仪器。','勿为“看腐蚀”故意损坏仪器。','碱腐蚀皮肤；规范取用。',0,'安全教育内容；勿自行用强碱破坏器皿。','pending_review','[inv:exp.SiO2_glass] 危险气体实验禁止家用; batch4导入 pending_review id=16',2,2,NULL,NULL,'2026-10-18 13:26:32.952','2026-10-18 13:44:52.000'),(17,'常见仪器识别与用途','instrument','书面分析题训练：识别试管、烧杯、量筒、酒精灯、漏斗、铁架台、集气瓶等常见仪器，并判断其主要用途与选用正误。','不同仪器按量取、加热、反应容器、过滤、收集等功能选用；容积刻度用途不同（如量筒量液、容量瓶定容）。','试管、烧杯、量筒、酒精灯、漏斗、铁架台（带铁圈/铁夹）、集气瓶、玻璃棒、胶头滴管等','无特定反应试剂（认知条目）','1.对照图示指出仪器名称；2.判断加热可否直接受热、是否需石棉网；3.判断量取精确度与适用场景；4.排除张冠李戴用途。','以图示与文字描述为依据作答，无实际操作现象。','能正确识别常见仪器并匹配用途，是后续操作正误与装置分析的基础。','量筒不可加热；容量瓶不能配制过程加热或长期存放溶液；胶头滴管不可平放、倒置或伸入他瓶。','酒精灯使用规范（灯帽、灯芯、禁对点）属安全判断考点；本题仅书面训练。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','pending_review','[inv:exp.instrument_basic] batch5导入 pending_review id=17',2,2,NULL,NULL,'2026-10-18 14:10:34.000','2026-10-18 16:49:11.000'),(18,'托盘天平称量','basic_ops','书面分析题训练：掌握托盘天平“左物右码”、游码读数、称量纸/器皿选用及常见操作错误对质量读数的影响。','托盘天平在游码归零调平后称量；物体质量≈砝码质量+游码读数。腐蚀性药品须放在玻璃器皿中称量。','托盘天平、砝码、镊子、称量纸或小烧杯/表面皿','固体药品（示例：NaCl 等，题设给出）','1.游码归零，调节平衡螺母使指针指零；2.左盘放物体，右盘放砝码；3.先加大砝码再调游码；4.读数并记录；5.砝码归盒，游码回零。','天平平衡时指针指零刻度（或左右摆动幅度相当）。','正确称量得到固体质量，是配制溶液与定量计算的数据来源。','不可用手直接拿砝码；潮湿或腐蚀性药品不能直接放托盘；称量完毕清扫托盘。','试剂勿入口、勿随意丢弃；仅书面分析操作正误与误差方向。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','pending_review','[inv:exp.ops_weigh] batch5导入 pending_review id=18',2,2,NULL,NULL,'2026-10-18 14:10:34.295','2026-10-18 16:49:12.000'),(19,'溶解与搅拌','basic_ops','书面分析题训练：判断固体溶解操作（烧杯、玻璃棒搅拌、加水顺序）及加速溶解措施的正误。','溶质在溶剂中分散形成溶液；搅拌可加快溶解，加热（若允许）也可加速，但须符合试剂性质与后续实验要求。','烧杯、玻璃棒、药匙、量筒（量取溶剂）','可溶性固体与蒸馏水（或题设溶剂）','1.固体放入烧杯；2.加入适量溶剂；3.用玻璃棒沿同一方向轻轻搅拌至溶解；4.若需定容，先溶解冷却再转移（见容量瓶条目）。','固体逐渐消失，溶液澄清（若完全溶解且无悬浮）。','规范溶解是配制溶液与后续过滤、蒸发等操作的前提。','玻璃棒不可碰破烧杯；搅拌勿溅出；热溶液须冷却后再定容或转移至怕热仪器。','强酸强碱溶解/稀释须按规定顺序（如浓硫酸酸入水）；禁止家用危险操作。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.ops_dissolve] batch5导入 pending_review id=19',2,2,NULL,NULL,'2026-10-18 14:10:34.472','2026-10-18 20:46:35.742'),(20,'过滤操作','basic_ops','书面分析题训练：掌握“一贴二低三靠”要点，判断滤纸、漏斗、玻璃棒、烧杯配合是否正确及滤液浑浊原因。','过滤利用滤纸孔隙分离不溶性固体与液体；滤液透过滤纸，残渣留在滤纸上。','漏斗、滤纸、玻璃棒、烧杯、铁架台（铁圈）','含不溶物的悬浊液（示例）','1.折滤纸贴紧漏斗内壁并湿润；2.漏斗下端紧靠接收烧杯内壁；3.玻璃棒引流，漏斗内液面低于滤纸边缘；4.滤渣洗涤（题设需要时）。','滤液澄清流下；固体留在滤纸上。','可分离不溶性固体与液体；滤液浑浊常因滤纸破损、液面过高或引流不当。','一贴二低三靠；倾倒时烧杯嘴紧靠玻璃棒；勿用玻璃棒戳破滤纸。','处理强酸强碱滤液须防溅伤；仅书面训练。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.ops_filter] batch5导入 pending_review id=20',2,2,NULL,NULL,'2026-10-18 14:10:34.775','2026-10-18 20:46:35.743'),(21,'蒸发结晶','basic_ops','书面分析题训练：认识蒸发皿蒸发浓缩/结晶的操作要点、加热与搅拌作用及何时停止加热。','加热使溶剂挥发，溶质浓度增大直至析出晶体；蒸发皿加热装置以题设图示/所用教材为准（常见为铁圈上放置蒸发皿加热；是否垫石棉网按题给装置判断，勿混写两种口径为同时必然）。','蒸发皿、玻璃棒、酒精灯、铁架台（铁圈）、石棉网（按装置要求）','溶液（如 NaCl 溶液等题设）','1.溶液盛于蒸发皿（不超过容积约2/3）；2.加热蒸发，并用玻璃棒不断搅拌；3.出现较多固体时停止加热，利用余热蒸干；4.冷却后转移晶体。','溶剂减少，逐渐析出晶体或固体。','可用于从溶液中得到可溶性固体；与过滤联用可分离可溶与不溶组分。','防止局部过热飞溅；勿蒸得过干导致固体迸溅；蒸发皿移取用坩埚钳。','加热防烫伤、防酒精灯事故；禁止家用自行加热实验。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','pending_review','[inv:exp.ops_evaporate] batch5导入 pending_review id=21',2,2,NULL,NULL,'2026-10-18 14:10:35.018','2026-10-18 16:49:15.000'),(22,'蒸馏操作认知','basic_ops','书面分析题训练：认识蒸馏分离沸点不同液体混合物的装置要点（温度计位置、冷凝管水流方向、防暴沸等），属认知级、不展开工业精馏。','加热使低沸点组分先汽化，经冷凝管冷凝后收集馏分，从而实现分离或提纯。','蒸馏烧瓶、温度计、冷凝管、接引管、锥形瓶、酒精灯、石棉网、沸石（或碎瓷片）','互溶且沸点不同的液体混合物（示例：乙醇与水，题设）','1.检查气密性并加入沸石；2.温度计水银球位于蒸馏烧瓶支管口处；3.冷凝管下口进水、上口出水；4.加热收集馏分；5.停火顺序与装置拆卸按规范。','馏分在接收器中逐渐增多；温度计读数对应馏出蒸气温度。','蒸馏可用于分离沸点相差较大的互溶液体；装置细节是常考正误点。','防暴沸；冷凝管水流方向不可反；液体体积不超过蒸馏烧瓶容积2/3。','易燃有机液体加热须远离明火隐患并规范操作；本产品仅书面认知，禁止家用蒸馏。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.ops_distill] priority2/认知级；勿按大学有机实验深度展开',2,2,NULL,NULL,'2026-10-18 14:10:35.199','2026-10-18 20:46:35.743'),(23,'分液与萃取认知','basic_ops','书面分析题训练：理解萃取（利用溶质在互不相溶溶剂中溶解度差异）与分液漏斗分液操作要点。','萃取剂与原溶剂互不相溶，溶质在萃取剂中溶解度更大时转入萃取剂层；静置分层后分液分离。','分液漏斗、烧杯、铁架台（铁圈）','互不相溶的两种液体及溶质（示例：碘水与四氯化碳，按教材题设）','1.分液漏斗检漏；2.加入液体，振荡并及时放气；3.静置分层；4.下层液体从下口放出，上层液体从上口倒出。','液体分为上下两层，颜色可能向萃取剂层转移（如碘的紫红色进入CCl4层）。','萃取+分液可分离或富集某些溶质；关键是溶剂选择与上下层判断。','振荡放气；分清上下层；下水从下口、上液从上口；有机溶剂使用按安全规范。','CCl4等有机溶剂有毒/环境危害，仅教材题设分析，禁止家用。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.ops_extract] 认知级；试剂示例随教材，勿鼓励实际操作',2,2,NULL,NULL,'2026-10-18 14:10:35.399','2026-10-18 20:46:35.743'),(24,'向上排空气法','gas_collect','书面分析题训练：根据气体密度与空气比较，判断何时用向上排空气法及导管伸入集气瓶的位置。','密度比空气大的气体可用向上排空气法：集气瓶口向上，导管伸入瓶底附近，空气从瓶口排出。','集气瓶、导管、发生装置（题设）','密度大于空气的气体示例：O2、CO2、Cl2（Cl2有毒，仅分析）等','1.集气瓶正放；2.导气管伸到接近瓶底；3.通气至收集满（按检验方法判断）；4.盖上玻璃片。','集气瓶内逐渐充满目标气体；可用相应检验方法确认（如O2复燃木条）。','适用于密度比空气大且不与空气成分显著反应的气体（结合溶解性等综合选题）。','导管位置过浅导致收集不纯；有毒气体须尾气处理（书面评价方案）。','有毒气体收集仅作装置分析；禁止接触或家用制取。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.gas_collect_upward] batch5导入 pending_review id=24',2,2,NULL,NULL,'2026-10-18 14:10:35.600','2026-10-18 20:46:35.743'),(25,'向下排空气法','gas_collect','书面分析题训练：判断密度比空气小的气体应采用向下排空气法及导管/瓶口朝向。','密度比空气小的气体可用向下排空气法：集气瓶口向下，导管伸入瓶底（此时为上方），空气被排出。','集气瓶、导管、发生装置（题设）','密度小于空气的气体示例：H2、NH3等','1.集气瓶倒放；2.导管伸到接近瓶底；3.通气收集；4.用合适方法检验是否收集满。','瓶内逐渐被轻气体占据；检验依气体而定（如H2可燃须先验纯——书面安全点）。','适用于密度比空气小的气体；常与溶解性、是否可用排水法综合考查。','勿与向上排空气法混淆瓶口方向；极易溶于水的气体如NH3一般不用排水法。','H2为易燃气体：书面强调验纯与禁明火；禁止家用制取氢气。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.gas_collect_downward] batch5导入 pending_review id=25',2,2,NULL,NULL,'2026-10-18 14:10:35.891','2026-10-18 20:46:35.744'),(26,'排水集气法','gas_collect','书面分析题训练：判断气体是否可用排水法（难溶或不易溶于水、不与水反应）及集气瓶装满水排气操作。','气体通入盛满水的集气瓶，将水排出而收集气体；适用于难溶/不易溶于水且不与水反应的气体。','集气瓶、水槽、导管、玻璃片','示例：O2、H2、NO（按题设；注意NO遇空气变化等干扰）等','1.集气瓶装满水，倒扣于水槽；2.导管伸入瓶内通气排水；3.收满后水下盖玻璃片取出；4.正放或倒放依气体密度（题设）。','瓶内水位下降，气体占据空间。','排水法可得到较纯净的难溶气体；易溶或与水反应的气体不适用。','导管口刚有气泡时先不急于收集（赶尽空气，按题目要求）；防倒吸视装置而定。','涉及H2等可燃气体时强调验纯；仅书面训练。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','pending_review','[inv:exp.gas_collect_water] batch5导入 pending_review id=26',2,2,NULL,NULL,'2026-10-18 14:10:36.066','2026-10-18 16:49:19.000'),(27,'高锰酸钾制氧气','gas_prep','书面分析题训练：分析KMnO4受热分解制O2的装置、加热位置、排水收集与导管进出顺序等正误。','2KMnO4=△=K2MnO4+MnO2+O2↑；O2可用排水法或向上排空气法收集。','试管、酒精灯、铁架台、导管、集气瓶、水槽、棉花（管口附近）等','KMnO4固体','1.检查气密性；2.装入KMnO4，管口放一团棉花，试管口略向下倾斜；3.加热；4.排水法收集；5.先撤导管再停热（防倒吸）。','产生能使带火星木条复燃的气体；固体颜色变化（题设描述）。','加热KMnO4可制O2；装置倾斜、棉花、撤管顺序为高频考点。','试管口向下倾斜防冷凝水流回炸裂；棉花防粉末堵塞；收集满后操作顺序正确。','加热实验有烫伤与炸裂风险；KMnO4强氧化性；本系统仅书面分析，禁止家用加热制气。',1,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.O2_prep_KMnO4] batch5导入 pending_review id=27',2,2,NULL,NULL,'2026-10-18 14:10:36.258','2026-10-18 20:46:35.744'),(28,'过氧化氢制氧气','gas_prep','书面分析题训练：认识H2O2在MnO2催化下分解制O2，比较与加热KMnO4法在装置、条件上的差异。','2H2O2=MnO2=2H2O+O2↑（MnO2为催化剂）；常温即可，常用分液漏斗/长颈漏斗加液。','锥形瓶或试管、分液漏斗或长颈漏斗、导管、集气瓶、水槽等','H2O2溶液、MnO2','1.检查气密性；2.瓶中加MnO2，分液漏斗加H2O2；3.滴加液体产生O2；4.排水或向上排空气法收集；5.检验：带火星木条复燃。','迅速产生气泡；带火星木条复燃。','催化分解H2O2可制O2，无需加热，适合与KMnO4法对比命题。','长颈漏斗下端须液封；控制滴加速度；催化剂用量与浓度按题设。','H2O2对皮肤有刺激/腐蚀性（浓度相关）；禁止家用随意催化制气；仅书面训练。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.O2_prep_H2O2] batch5导入 pending_review id=28',2,2,NULL,NULL,'2026-10-18 14:10:36.441','2026-10-18 20:46:35.744'),(29,'锌与稀硫酸制氢气','gas_prep','书面分析题训练：分析Zn与稀硫酸制H2的发生装置、收集方法、验纯与安全判断；不要求也不允许实际操作。','Zn+H2SO4=ZnSO4+H2↑；H2密度比空气小、难溶于水，可用向下排空气法或排水法收集。','试管或锥形瓶、长颈漏斗或分液漏斗、导管、集气瓶、水槽等','锌粒、稀硫酸（不可用浓硫酸按此式简单代替）','1.检查气密性；2.加锌粒，注入稀硫酸；3.收集H2；4.点燃前必须验纯（书面强调）；5.规范处理残液。','锌粒表面产生气泡；收集的气体可燃（安静燃烧淡蓝色火焰——验纯合格后）。','活泼金属与非氧化性稀酸可制H2；收集与验纯是安全与装置题核心。','验纯；防点燃不纯气体爆炸；装置导管位置正确；勿用浓硫酸与此性质简单混用。','H2为易燃气体，不纯时点燃可能爆炸；严禁在家制取或点燃氢气。本系统仅做书面现象、操作、安全与装置分析。',1,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.H2_prep_Zn] 易燃气体；书面训练专用；强安全提示',2,2,NULL,NULL,'2026-10-18 14:10:36.649','2026-10-18 20:46:35.744'),(30,'大理石与稀盐酸制二氧化碳','gas_prep','书面分析题训练：掌握CaCO3与稀盐酸制CO2的装置选择、收集（向上排空气法）及除杂/检验思路。','CaCO3+2HCl=CaCl2+H2O+CO2↑；CO2密度比空气大，可用向上排空气法；一般不用排水法（可溶）。','锥形瓶、分液漏斗或长颈漏斗、导管、集气瓶、洗气瓶（除杂题设）等','大理石（或石灰石）、稀盐酸；澄清石灰水（检验）','1.检查气密性；2.固体+酸反应发生CO2；3.向上排空气法收集；4.通入澄清石灰水检验变浑浊；5.尾气与废液按题设处理。','产生气泡；石灰水变浑浊；燃烧木条熄灭（性质题）。','实验室常用大理石与稀盐酸制CO2；不用稀硫酸（生成微溶CaSO4覆盖，反应减弱——常考）。','长颈漏斗液封；收集满判断；若除HCl可用相应洗气试剂（见洗气知识点）。','盐酸腐蚀性；高浓度CO2窒息风险；仅书面训练，禁止家用制气实验。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.CO2_prep_marble] batch5导入 pending_review id=30',2,2,NULL,NULL,'2026-10-18 14:10:36.879','2026-10-18 20:46:35.745'),(31,'装置气密性检查','basic_ops','书面分析题训练：在加入试剂前检查气密性的方法、现象判断及“先检后装”的操作顺序评价。','封闭体系内气压变化（微热或移动）会使导管口气泡/水柱出现可观察现象，据此判断是否漏气。','待检发生装置、导管、水槽或烧杯、酒精灯（微热法）等','水（观察用）；正式试剂在检漏合格后再加入','1.按装置连接（未加反应物）；2.导管口浸入水中；3.微热容器（或用手捂）观察气泡；4.冷却后导管内形成一段稳定水柱则气密性良好；5.合格后再加药品。','气密性好：加热有气泡，冷却形成水柱；漏气则无明显水柱或很快回落。','气密性检查是制气实验必要步骤；漏气导致收集失败或定量误差。','先检查后加药品；加热不可过猛；有分液漏斗时活塞状态要符合检漏要求。','检漏加热防烫伤；仅书面步骤排序与正误判断。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.check_airtight] batch5导入 pending_review id=31',2,2,NULL,NULL,'2026-10-18 14:10:37.046','2026-10-18 20:46:35.745'),(32,'实验室安全通则','safety','书面分析题训练：判断实验室着装、试剂取用、加热、急救与废弃物处理等安全正误，强化“禁止家用危险实验”意识。','化学实验室通过规范操作、通风、防护与应急降低风险；安全规则服务于事故预防与正确处置。','护目镜、实验服等防护用品（认知）；灭火毯/沙等应急设施（了解）','各类试剂的通用安全原则（按标签与性质）','1.阅读题设操作或场景；2.对照通则判断对错；3.指出正确做法（如稀释顺序、嗅气体方法、洒落处理）；4.区分实验室规范与家用禁止。','无实验现象；以规则判断与案例分析为主。','遵守安全通则是一切实验活动的前提；本产品训练止于书面判断。','不能用手直接接触药品、不能品尝；加热试管口不对人；酒精灯禁对点；事故按教材急救口径作答。','强酸强碱、火、有毒气体等场景仅作文案分析；明确禁止学生在家庭环境自行实验。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.safety_rules] batch5导入 pending_review id=32',2,2,NULL,NULL,'2026-10-18 14:10:37.141','2026-10-18 20:46:35.745'),(33,'容量瓶定容操作','basic_ops','书面分析题训练：掌握配制一定物质的量浓度溶液时容量瓶定容步骤、误差阶段分析，并关联 c=n/V 计算。','容量瓶在标定温度下准确容纳一定体积溶液；定容至凹液面最低处与刻度线相切，摇匀后得到目标体积。','容量瓶、烧杯、玻璃棒、胶头滴管、药匙、天平（称固体时）','溶质固体或浓溶液（题设）与蒸馏水','1.查漏；2.烧杯溶解（或稀释）并冷却至室温；3.引流转移并洗涤；4.加水至刻度线近处，改用胶头滴管定容；5.盖塞颠倒摇匀。','凹液面与刻度线相切；溶液混合均匀。','定容操作直接影响溶液体积V，从而影响浓度c；误差须对应溶解/转移/定容等阶段分析。','不能加热容量瓶；不能在容量瓶中溶解固体；俯视/仰视刻度导致V偏差方向相反。','配制强酸强碱溶液防溅；仅书面训练与计算联动。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.ops_volumetric_flask] 与kp.calc.solution、kp.exp.error联动',2,2,NULL,NULL,'2026-10-18 14:10:37.216','2026-10-18 20:46:35.747'),(34,'滴定管认知与基本操作','instrument','书面分析题训练：识别酸式/碱式滴定管、读数（凹液面）与基本使用注意；不按分析化学滴定分析深度展开。','滴定管可精确放出液体并读出体积；酸式滴定管有玻璃活塞，碱式滴定管有橡胶管与玻璃珠（防碱腐蚀玻璃活塞）。','酸式滴定管、碱式滴定管、滴定管夹、烧杯、锥形瓶（认知配合）','示例酸碱溶液（题设）；不展开指示剂选择理论','1.查漏与洗涤；2.注入溶液并赶尽尖嘴气泡；3.调液面并记录初读数；4.放出液体后读终读数；5.计算放出体积=终读−初读。','液面下降；读数为凹液面最低点。','滴定管用于精确量取/放出液体体积；酸式与碱式不可混用（试剂性质）。','酸式不能盛碱；碱式不能盛酸或强氧化性溶液（橡胶）；读数视线与凹液面相平。','酸碱腐蚀；本条为仪器认知，是否作为必修核心训练待核实。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','pending_review','[inv:exp.ops_burette] 待核实是否必修核心；避免分析化学滴定深度',2,2,NULL,NULL,'2026-10-18 14:10:37.383','2026-10-18 16:49:25.000'),(35,'焰色反应','substance_test','书面分析题训练：根据焰色判断常见金属元素（如Na、K、Cu），并认识观察K时透过钴玻璃的作用。','某些金属或其化合物在无色火焰中灼烧时使火焰呈现特征颜色，称为焰色反应；属于物理变化（没有生成新物质），可用于初步检验某些金属元素。','铂丝或光洁铁丝/镍铬丝、酒精灯、钴玻璃（观察钾）、盐酸（洗净用，题设）','含Na+、K+、Cu2+等的化合物样品（题设）','1.金属丝蘸稀盐酸后在火焰上灼烧至无色；2.蘸取样品灼烧观察焰色；3.观察钾的焰色时透过蓝色钴玻璃；4.对比题给颜色作判断。','钠：黄色；钾：紫色（透过钴玻璃观察，可滤去钠黄光干扰）；铜：绿色（高中常见表述，以所用教材为准）。','焰色反应可辅助检验某些金属离子；有钠干扰时观察钾需用钴玻璃。','金属丝须烧至无色再蘸样；区分焰色与物质本身颜色；不要把所有金属都当成有明显焰色。','酒精灯与灼烧防烫伤；禁止家用危险加热操作；仅书面颜色与操作判断。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','pending_review','[inv:exp.flame_test] Na/K/Cu颜色以人教必修常见表述；钴玻璃观察K；具体措辞待对照所用教材核实',2,2,NULL,NULL,'2026-10-18 14:10:37.475','2026-10-18 16:49:26.000'),(36,'甲烷性质实验认知','property','书面分析题训练：认识甲烷的可燃性及光照下与氯气取代的主要现象与结论，理解多种氯代产物可能并存。','甲烷可燃烧生成CO2和H2O。光照下与Cl2发生取代，可生成CH3Cl、CH2Cl2、CHCl3、CCl4等多种产物，不得写为唯一产物。','集气瓶、导管、光源（题设）、燃烧匙或导管点燃装置（图示）等','CH4、Cl2、空气/O2（燃烧题设）','1.对照图示判断气体验纯与点燃要点；2.分析CH4与Cl2混合光照的现象描述；3.判断产物是否可能为混合物；4.安全与尾气评价（书面）。','燃烧；氯气黄绿色变浅、可能出现油状液滴；生成HCl使石蕊变红（题设）。','甲烷可燃；光照下可发生取代且产物多样；实验仅作现象与原理书面训练。','混合气体遇火源危险；Cl2有毒须尾气处理；禁止家用。','本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。 氯气与可燃气体实验高危，禁止动手。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.CH4_property] 书面only;多种氯代产物',2,2,NULL,NULL,'2026-10-18 17:05:17.798','2026-10-18 20:46:35.752'),(37,'乙烯的实验室制法','gas_prep','书面分析题训练：掌握乙醇浓硫酸加热制乙烯的原理、温度控制、装置与杂质干扰评价要点。','实验室常用乙醇与浓硫酸混合加热至约170℃制乙烯（消去，教材表述）：CH3CH2OH →浓H2SO4、170℃→ CH2=CH2↑ + H2O。温度不当可能生成乙醚等副产物（了解/题设）。','圆底烧瓶、温度计、酒精灯、导管、集气瓶或后续性质检验装置等','乙醇、浓硫酸；碎瓷片（防暴沸，题设）','1.检查气密性；2.按比例加入试剂与碎瓷片；3.迅速升温至约170℃；4.收集或通入后续试剂检验；5.评价尾气与废液处理（书面）。','产生气体；后续可使溴水或酸性KMnO4褪色（性质联动题设）。','可用乙醇浓硫酸加热制乙烯；温度与防暴沸是常考点。','温度计水银球位置；防暴沸；浓硫酸腐蚀；控制温度减少副反应。','本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。 浓硫酸加热高危，禁止家用。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.C2H4_prep] 约170℃;书面装置分析',2,2,NULL,NULL,'2026-10-18 17:05:17.908','2026-10-18 20:46:35.753'),(38,'乙烯使溴水褪色','property','书面分析题训练：用溴水（或溴的四氯化碳溶液）检验乙烯不饱和性，区分加成褪色与萃取等干扰。','CH2=CH2+Br2→CH2BrCH2Br（加成），溶液颜色褪去；属于化学变化导致的褪色。','导管、试管或洗气瓶、集气装置（题设）','乙烯、溴水（或Br2/CCl4）','1.将乙烯通入溴水；2.观察颜色变化；3.与甲烷/乙烷对照（题设）；4.判断褪色原因是否为加成。','溴水橙红/棕红色褪去。','乙烯能与溴加成使溴水褪色，可用于检验不饱和键。','溴水有腐蚀性与毒性；通入速率与装置气密性（书面评价）。','本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。 溴试剂危险，禁止家用。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.C2H4_Br2] batch6导入 pending_review id=38',2,2,NULL,NULL,'2026-10-18 17:05:17.995','2026-10-18 20:46:35.753'),(39,'乙醇催化氧化','property','书面分析题训练：认识乙醇在Cu或Ag催化加热下被氧气氧化为乙醛的条件、现象与方程式。','2CH3CH2OH+O2=Cu或Ag、加热=2CH3CHO+2H2O。常见演示：铜丝加热变黑（CuO）后伸入乙醇，又变为红色，循环催化。','酒精灯、铜丝（或银丝）、试管等（题设图示）','乙醇、空气（O2）、Cu或Ag','1.加热铜丝至表面变黑；2.趁热伸入乙醇液面上方或按教材操作；3.观察铜丝颜色变化与气味；4.写出化学方程式并标明条件。','铜丝由黑变红；可闻到刺激性气味（乙醛）。','乙醇可催化氧化为乙醛；条件必须写清催化剂与加热。','乙醇易燃，远离明火隐患；仅书面分析操作正误。','本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。 禁止家用加热有机物实验。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.ethanol_oxid] batch6导入 pending_review id=39',2,2,NULL,NULL,'2026-10-18 17:05:18.336','2026-10-18 20:46:35.753'),(40,'乙酸乙酯制备','organic_prep','书面分析题训练：掌握酯化反应条件、装置要点、饱和碳酸钠溶液作用及产物分层现象分析。','CH3COOH+C2H5OH⇌浓硫酸、加热⇌CH3COOC2H5+H2O。浓硫酸催化并吸水；产物用饱和Na2CO3吸收乙酸、溶解乙醇并降低酯溶解度，便于分层观察。','大试管、导管、酒精灯、接收试管等','乙酸、乙醇、浓硫酸、饱和碳酸钠溶液','1.按顺序加入试剂（题设常考加料顺序）；2.加热；3.导管口在液面上防倒吸（题设）；4.观察上层油状有香味液体；5.评价可逆与提高产率措施（书面）。','有香味；在饱和Na2CO3液面上出现油状液体层。','可制得乙酸乙酯；反应可逆；饱和碳酸钠有助于观察与分离酯。','浓硫酸腐蚀；加热防暴沸/液体冲出；导管不可伸入碳酸钠液面下过深导致倒吸（题设）。','本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。 禁止家用酯化实验。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.esterification] batch6导入 pending_review id=40',2,2,NULL,NULL,'2026-10-18 17:05:18.453','2026-10-18 20:46:35.754'),(41,'乙酸酸性验证','property','书面分析题训练：通过石蕊、与活泼金属、碱、碳酸盐等反应验证乙酸酸性及“强于碳酸”的比较。','乙酸为弱酸但具酸通性；2CH3COOH+Na2CO3=2CH3COONa+CO2↑+H2O，可证明酸性强于碳酸。','试管、胶头滴管、导管、澄清石灰水等','乙酸、紫色石蕊、镁条（或锌）、NaOH、Na2CO3、澄清石灰水','1.石蕊变红；2.与活泼金属产生气泡；3.与NaOH中和；4.与Na2CO3反应，气体通入石灰水变浑浊；5.对比结论。','石蕊变红；有气泡；石灰水变浑浊等。','乙酸具酸性；酸性强于碳酸。','浓乙酸腐蚀刺激；气体检验注意量与装置。','本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.acetic_acid] batch6导入 pending_review id=41',2,2,NULL,NULL,'2026-10-18 17:05:18.527','2026-10-18 20:46:35.754'),(42,'铜锌原电池实验','electrochem','书面分析题训练：分析Zn-Cu原电池的电极、电子流向、离子迁移及电解质不同时正极反应的差异。','原电池将化学能转化为电能。电子经外电路从负极流向正极；溶液中阴、阳离子定向迁移形成闭合回路。负极：较活泼金属Zn失电子被氧化。正极还原反应取决于电解质：①电解质为CuSO4时，正极通常Cu2++2e-=Cu；②电解质为稀H2SO4时，正极通常2H++2e-=H2↑。须按题设电解质判断，不可混用。并非所有原电池都必须是两种不同金属（电极材料组合以题设为准）。','锌片、铜片、导线、电流计（或小灯泡）、烧杯等（图示）','Zn、Cu；CuSO4溶液或稀H2SO4（题设二选一或对照）','1.辨认电极与电解质；2.判断负极氧化、正极还原；3.标出电子外电路方向；4.说明离子在溶液中的迁移；5.对照CuSO4与稀H2SO4两种题设写电极反应。','电流计偏转或灯泡发光；锌片溶解；CuSO4中铜片上可析出铜；稀硫酸中铜片上可有气泡（题设）。','能构成原电池并产生电流；电子走外电路、离子走电解质；正极反应随电解质而变。','电极与电解质匹配；书写电极反应须与题设一致；仅书面分析。','本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。 纸面分析，不要求动手。',0,'本系统仅做书面题目训练（现象判断、操作正误、步骤排序、结论推断、装置分析、误差分析、方案评价、安全判断），不要求学生线下动手操作；禁止家用自行实验。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:exp.galvanic_Zn_Cu] 电解质CuSO4 vs 稀H2SO4正极不同;电子外电路;离子溶液迁移',2,2,NULL,NULL,'2026-10-18 17:05:18.668','2026-10-18 20:46:35.838');
