INSERT INTO `chem_formulas` VALUES (1,'物质的量与质量关系','n = m / M','n:物质的量；m:质量；M:摩尔质量','n:mol；m:g；M:g/mol','适用于纯净物定量换算','18g水：n=18/18=1mol','混淆摩尔质量与相对分子质量单位','published','',NULL,NULL,NULL,NULL,'2026-10-18 09:49:45.975','2026-10-18 09:49:45.975'),(2,'粒子数与物质的量','N = n · NA','N:粒子数；n:物质的量；NA:阿伏加德罗常数','N无量纲计数；n:mol；NA:mol^-1','微观粒子数与物质的量换算','2 mol H2O含分子数 2·NA','把NA当成有单位“个”而忘记 mol^-1','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.N_n_NA]',2,2,NULL,NULL,'2026-10-18 11:38:24.844','2026-10-18 20:46:35.467'),(3,'气体摩尔体积','Vm = V / n','Vm:气体摩尔体积；V:气体体积；n:物质的量','Vm:L/mol；V:L；n:mol','定义式 Vm=V/n 适用于气体。Vm 随温度、压强变化。仅当题目指明标准状况（0℃、101kPa）时，才可近似用 Vm≈22.4 L/mol；常温常压不可默认22.4。标况专用也可参见 formula.gas_STP。','标况下 0.5 mol 气体体积约 11.2 L','非气体套用；非标况仍用22.4；把定义式与标况近似值混为一谈','pending_review','[inv:formula.Vm] B2整改:区分定义式与标况近似',2,2,NULL,NULL,'2026-10-18 11:38:24.930','2026-10-18 12:15:36.728'),(4,'物质的量浓度','c = n / V','c:物质的量浓度；n:溶质物质的量；V:溶液体积','c:mol/L；n:mol；V:L','溶液浓度定义','1 mol NaOH溶于水配成 1 L 溶液，c=1 mol/L','把溶剂体积当成溶液体积','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.c_n_V]',2,2,NULL,NULL,'2026-10-18 11:38:24.996','2026-10-18 20:46:35.467'),(5,'溶液稀释','c1V1 = c2V2','稀释前后溶质的物质的量不变','c:mol/L；V:L','只加水稀释，溶质不损失','2 mol/L×0.1 L = 0.5 mol/L×0.4 L','用于发生反应的混合过程仍直接套用','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.dilution]',2,2,NULL,NULL,'2026-10-18 11:38:25.080','2026-10-18 20:46:35.468'),(6,'摩尔质量','M = m / n','M:摩尔质量；m:质量；n:物质的量','M:g/mol；m:g；n:mol','适用于纯净物：m 为该纯净物质量。M 的数值等于相对原子/分子质量，单位必须写 g/mol。与聚集状态无关；勿与气体体积公式混用。与 formula.n_m_M 互为变形。','水的 M≈18 g/mol','把相对分子质量数值当成有单位却写错单位','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.M_m_n] B2整改:补单位与适用说明',2,2,NULL,NULL,'2026-10-18 11:38:25.186','2026-10-18 20:46:35.468'),(7,'密度与浓度换算','c = 1000ρω/M','ρ:溶液密度；ω:溶质质量分数（小数）；M:溶质摩尔质量；c:物质的量浓度','当 ρ 取 g/cm³（或 g/mL，二者数值相同）且 ω 为小数时：c 单位为 mol/L，M 单位为 g/mol。若密度改用 g/L，则公式改为 c = ρω/M（不再乘 1000）。','由溶液密度与溶质质量分数换算物质的量浓度；ω 必须用小数（如 98% 写作 0.98），不能直接代入百分数；ρ 与公式系数必须匹配（g/cm³ 用含 1000 的式，g/L 用不含 1000 的式）。','浓硫酸标签：ρ=1.84 g/cm³，ω=0.98，M(H2SO4)=98 g/mol，则 c=1000×1.84×0.98/98≈18.4 mol/L。','把 ω 直接写成 98；ρ 用 g/L 却仍乘 1000；混淆溶剂体积与溶液体积；把相对分子质量数值当摩尔质量却漏写单位 g/mol。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.rho_c_M] P0已修:明确 ρ(g/cm³)+ω(小数)+1000 系数；g/L 时用 c=ρω/M',2,2,NULL,NULL,'2026-10-18 11:38:25.280','2026-10-18 20:46:35.469'),(8,'质量分数','w = m(溶质) / m(溶液)','w:质量分数','无量纲（常以%表示）','溶液组成表示','10 g 溶质溶于 90 g 水，w=10%','分母写成溶剂质量','pending_review','[inv:formula.mass_percent]',2,2,NULL,NULL,'2026-10-18 11:38:25.363','2026-10-18 11:38:25.363'),(9,'化学计量比','n_A / a = n_B / b','化学方程式 aA+bB→… 中计量数之比等于物质的量之比','n:mol','按化学方程式计量关系计算：仅当反应物按计量完全反应，或先按不足量（限量反应物）折算后再用。有杂质、转化率、过量时，需先处理实际参与反应的物质的量。','2H2+O2→2H2O 中 n(H2):n(O2)=2:1','用质量比直接代替物质的量比；忽略过量/不足；未考虑转化率或纯度','pending_review','[inv:formula.equation_ratio] B2整改:补过量与不足量条件',2,2,NULL,NULL,'2026-10-18 11:38:25.430','2026-10-18 12:15:36.729'),(10,'电子转移计量','失电子总数 = 得电子总数','氧化还原配平依据','电子数','氧化还原反应','双线桥法标注转移电子数相等','只配平元素不配平电子','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.electron_transfer]',2,2,NULL,NULL,'2026-10-18 11:38:25.513','2026-10-18 20:46:35.469'),(11,'标况气体体积','V = n · 22.4 L/mol（标准状况近似）','V:气体体积；n:物质的量；标准状况：0℃（273K）、101kPa','V:L；n:mol；22.4:L/mol（标况近似）','仅适用于标准状况（0℃、101kPa）下的气体（理想气体近似）。常温常压、非标况气体不可套用22.4。一般气体摩尔体积定义见 formula.Vm。','1 mol 任何气体标况下约 22.4 L','常温常压仍用22.4；非气体套用；未看清题设是否“标准状况”','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.gas_STP] B2整改:写明0℃、101kPa',2,2,NULL,NULL,'2026-10-18 11:38:25.596','2026-10-18 20:46:35.469'),(12,'阿伏加德罗常数定义','NA ≈ 6.02×10^23 mol^-1','阿伏加德罗常数','mol^-1','微观计数与物质的量联系','1 mol 粒子约含 6.02×10^23 个','把 NA 当成“永远精确等于”某值而忽略测定含义','pending_review','[inv:formula.Avogadro]',2,2,NULL,NULL,'2026-10-18 11:38:25.689','2026-10-18 11:38:25.689'),(13,'多步方程式计算关系式法','由多步反应消去中间产物，得起始反应物与最终产物的计量关系式，再按 n 比例计算','各步化学方程式计量数；中间产物（消去）；目标产物物质的量或质量','n:mol；m:g；气体标况下可用 V 与 22.4 L/mol（仅标况）','连续多步反应且中间产物完全转化时可写关系式；有过量、转化率、纯度时须先处理实际转化的量。','若 A→B→C 中计量关系可写成 aA ∼ cC，则已知 n(A) 可直接求 n(C)，无需逐步求中间量。','不会消去中间产物；把质量比当物质的量比；忽略某步转化不完全。','pending_review','[inv:formula.mixed_stoich] batch5导入 pending_review id=13',2,2,NULL,NULL,'2026-10-18 14:11:07.992','2026-10-18 16:49:27.000'),(14,'过量计算判断','比较 n(实)/计量数：较小者为不足量（限量），按不足量计算产物','各反应物实际物质的量；化学方程式计量数','n:mol','给出两种及以上反应物用量时必须先判断过量；只有不足量完全反应。','2H2+O2=2H2O：若 n(H2)=3 mol、n(O2)=1 mol，则 n(H2)/2=1.5 > n(O2)/1=1，O2不足，按 O2 计算。','不判断过量直接代入；用质量比代替物质的量比与计量数比较。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.excess_reactant] batch5导入 pending_review id=14',2,2,NULL,NULL,'2026-10-18 14:11:08.171','2026-10-18 20:46:35.746'),(15,'纯度与产率','纯度=纯物质质量/样品质量×100%；产率=实际产量/理论产量×100%','纯物质质量；样品（粗产品）质量；实际产量；按计量算得的理论产量','质量单位须一致；产率、纯度常用%','纯度针对样品中目标成分含量；产率须先按不足量与方程式算理论产量，再与实际产量比较。','理论得10 g产物，实际8 g，产率=80%；样品10 g含纯物质9 g，纯度=90%。','产率分母用实际产量；纯度分母用纯物质；理论产量未按不足量计算。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.purity] batch5导入 pending_review id=15',2,2,NULL,NULL,'2026-10-18 14:11:08.445','2026-10-18 20:46:35.746'),(16,'离子浓度计算入门','强电解质按化学式完全电离：c(离子)=c(电解质)×离子下标（简单情形）','c(电解质)；电离出的离子个数（化学式中下标）','c:mol/L','适用于强酸、强碱、可溶性强电解质盐的简单完全电离；不涉及弱电解质Ka、水解与电荷守恒联立等平衡计算。','0.1 mol/L Na2SO4 中 c(Na+)=0.2 mol/L，c(SO4 2-)=0.1 mol/L。','弱电解质按完全电离算；忽略正负离子浓度与电荷关系；与质量分数混淆。','pending_review','[inv:formula.ion_conc] 禁Ka平衡计算；仅入门强电解质',2,2,NULL,NULL,'2026-10-18 14:11:08.617','2026-10-18 16:49:29.000'),(17,'化学反应速率定义式','v = Δc / Δt（平均速率）','v:化学反应速率；Δc:浓度变化量；Δt:时间变化量','常用 mol/(L·s) 或 mol/(L·min) 等，须与题设一致','高中常用某段时间内的平均速率；可用不同物质表示，数值与计量数相关；不展开选修复杂速率方程。','若Δc(A)=0.2 mol/L，Δt=10 s，则用A表示的平均速率 v(A)=0.02 mol/(L·s)。','单位漏写或与Δt不匹配；把瞬时速率公式超纲套用；混淆速率与平衡转化率。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:formula.rate_v] 平均速率口径；非选修深度',2,2,NULL,NULL,'2026-10-18 14:11:08.740','2026-10-18 20:46:35.747');
/*!40000 ALTER TABLE `chem_formulas` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `chem_concepts`
--

DROP TABLE IF EXISTS `chem_concepts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chem_concepts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(128) NOT NULL,
  `definition` text,
  `principle` text,
  `applicable_conditions` text,
  `judge_methods` text,
  `examples` text,
  `common_mistakes` text,
  `status` varchar(32) NOT NULL DEFAULT 'draft',
  `review_note` varchar(255) NOT NULL DEFAULT '',
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `reviewed_by` bigint unsigned DEFAULT NULL,
  `reviewed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_chem_concept_status` (`status`),
  KEY `idx_chem_concept_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `chem_concepts`
--

LOCK TABLES `chem_concepts` WRITE;
/*!40000 ALTER TABLE `chem_concepts` DISABLE KEYS */;
INSERT INTO `chem_concepts` VALUES (1,'氧化还原反应','有电子转移（或化合价升降）的反应','氧化与还原同时发生，得失电子守恒','存在化合价变化的化学反应','看化合价是否升降；找氧化剂还原剂','2Na+2H2O=2NaOH+H2↑','把有氧参与才叫氧化；忽略电子守恒','published','',NULL,NULL,NULL,NULL,'2026-10-18 09:49:46.058','2026-10-18 09:49:46.058'),(2,'物质的分类','按组成与性质，常把物质分为纯净物与混合物；纯净物再分为单质与化合物；化合物中常见氧化物、酸、碱、盐等。','分类是为了认识物质组成与转化规律，同一物质可按不同标准归类。','高中必修范围内的常见物质分类讨论。','先看是否纯净；再看是否由同种元素组成；化合物再看是否含氧、是否电离出H+/OH-等。','O2是单质；H2O是化合物；空气是混合物；NaOH是碱；HCl是酸；NaCl是盐。','把合金当成纯净物；把氧化物都当成酸性或碱性而不加区分。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.substance_class]',2,2,NULL,NULL,'2026-10-18 11:38:20.926','2026-10-18 20:46:35.460'),(3,'纯净物与混合物','纯净物由一种物质组成；混合物由两种或多种物质混合而成，各成分保持原有性质。','纯净物有固定组成（化合物有确定化学式）；混合物组成可变。','宏观组成判断；不考虑同位素等微观细微差异时的中学定义。','看能否用一种化学式表示；看各部分性质是否一致。','蒸馏水可视为纯净物；海水、空气、合金是混合物。','认为纯净物一定是单质；认为混合物一定能用物理方法轻易分开。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.pure_mixture]',2,2,NULL,NULL,'2026-10-18 11:38:21.010','2026-10-18 20:46:35.460'),(4,'单质与化合物','单质是由同种元素组成的纯净物；化合物是由不同种元素组成的纯净物。','元素是具有相同核电荷数（质子数）的一类原子的总称；单质是元素的游离态形式之一。','讨论物质组成时。','先确认是纯净物，再看化学式中元素种类：一种元素→单质；多种元素→化合物。注意O₂与O₃的混合物不是单质。','O2、金刚石是单质；CO2、NaCl是化合物。','漏掉“纯净物”条件；把O₂与O混淆；把CO当成单质。注意：Co是钴，CO是一氧化碳。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.elemental_compound] B2整改:定义补“纯净物”',2,2,NULL,NULL,'2026-10-18 11:38:21.053','2026-10-18 20:46:35.460'),(5,'电解质','在水溶液中或熔融状态下能够导电的化合物叫做电解质。','导电是因为存在自由移动的离子；电解质导电不等于单质金属导电。','讨论酸碱盐等化合物的电离与导电性。','看是否为化合物，以及水溶液或熔融时能否电离出自由移动离子。','NaCl、H2SO4、NaOH是电解质；蔗糖、酒精通常是非电解质。','把能导电的都叫电解质（金属单质能导电但不是电解质）；把电解质溶液导电当成电解质本身一定是离子晶体。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.electrolyte]',2,2,NULL,NULL,'2026-10-18 11:38:21.085','2026-10-18 20:46:35.461'),(6,'非电解质','在水溶液中和熔融状态下都不能导电的化合物叫做非电解质。','非电解质分子不电离（或几乎不电离）出自由移动离子。','化合物导电性分类。','化合物且水溶液、熔融都不导电。','蔗糖、酒精、尿素等。','把单质金属、石墨当成非电解质；把CO2、SO2等本身不电离但与水反应生成电解质的物质简单归类时要说明“本身是非电解质”。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.nonelectrolyte]',2,2,NULL,NULL,'2026-10-18 11:38:21.119','2026-10-18 20:46:35.461'),(7,'电离','电解质在水溶液中或熔融状态下离解成自由移动离子的过程叫做电离。','电离不需要通电；电解才是通电发生化学反应。','强电解质可认为完全电离；弱电解质部分电离（高中初步）。','写电离方程式，注意守恒与拆分规则。','NaCl=Na++Cl-；H2SO4=2H++SO42-。','把电离写成需要通电；强酸弱酸盐等拆分错误。','pending_review','[inv:concept.ionization]',2,2,NULL,NULL,'2026-10-18 11:38:21.160','2026-10-18 11:38:21.160'),(8,'离子反应本质','有离子参加的反应叫做离子反应；实质常是某些离子浓度减小（生成沉淀、气体或水等）。','用离子方程式表示实际参加反应的离子。','电解质在溶液中的反应。','写出完整式→拆成离子→删去未变离子→检查原子与电荷守恒。','AgNO3与NaCl：Ag++Cl-=AgCl↓。','弱电解质、沉淀、气体、单质不拆；电荷不守恒。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.ionic_reaction]',2,2,NULL,NULL,'2026-10-18 11:38:21.193','2026-10-18 20:46:35.461'),(9,'离子共存条件','同一溶液中多种离子能否大量共同存在，取决于它们之间是否会发生反应而使某些离子大量减少。','若能生成沉淀、气体、水或发生氧化还原等，则通常不能大量共存。','无色透明溶液等题设条件下的判断题。','两两检查是否反应；注意酸碱性、氧化还原。','H+与OH-不能大量共存；Ba2+与SO42-不能大量共存。','忽略弱酸酸式酸根与H+/OH-；忽略氧化还原共存。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.ion_coexist]',2,2,NULL,NULL,'2026-10-18 11:38:21.227','2026-10-18 20:46:35.462'),(10,'氧化剂与还原剂','氧化剂是得到电子（化合价降低）的物质；还原剂是失去电子（化合价升高）的物质。','氧化与还原同时发生；电子得失守恒。','有化合价变化的反应。','标化合价→看升降→升的是还原剂，降的是氧化剂。','2Na+Cl2=2NaCl中，Cl2是氧化剂，Na是还原剂。','把“有氧参加”才叫氧化；混淆氧化剂与氧化产物。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.oxidant_reductant]',2,2,NULL,NULL,'2026-10-18 11:38:21.260','2026-10-18 20:46:35.462'),(11,'化合价规则','化合价表示元素原子形成化合物时的化合能力；常见规则可帮助书写化学式。','化合物中正负化合价代数和为零。','书写化学式、判断氧化还原时。','记常见价：O通常-2，H通常+1，碱金属+1等。','H2O中H为+1、O为-2；Al2O3中Al为+3。','过氧化物中O为-1；单质中化合价为0。','pending_review','[inv:concept.valence_rules]',2,2,NULL,NULL,'2026-10-18 11:38:21.294','2026-10-18 11:38:21.294'),(12,'元素周期律','元素的性质随着原子序数的递增而呈周期性变化的规律叫做元素周期律。','周期性根源是核外电子排布的周期性。','同周期、同主族递变比较。','同周期从左到右金属性减弱、非金属性增强；同主族从上到下金属性增强等。','第三周期Na到Cl的性质递变。','把相对原子质量当成周期律的自变量（近代以原子序数为准）。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.periodic_law]',2,2,NULL,NULL,'2026-10-18 11:38:21.353','2026-10-18 20:46:35.462'),(13,'金属性递变','同周期从左到右金属性减弱；同主族从上到下金属性增强（主族规律）。','与原子半径、失电子能力相关。','主族元素比较；过渡元素更复杂。','比与水/酸反应难易，比最高价氧化物对应水化物碱性强弱等。','金属性K>Na>Li；Na>Mg>Al。','用密度、硬度直接代替金属性强弱。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.metal_trend]',2,2,NULL,NULL,'2026-10-18 11:38:21.395','2026-10-18 20:46:35.463'),(14,'非金属性递变','同周期从左到右非金属性增强；同主族从上到下非金属性减弱（主族规律）。','与得电子能力相关。','卤族、氧族等比较。','比单质氧化性、氢化物稳定性、最高价含氧酸酸性等。','非金属性F>Cl>Br>I。','把单质颜色、状态直接等同于非金属性强弱。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.nonmetal_trend]',2,2,NULL,NULL,'2026-10-18 11:38:21.453','2026-10-18 20:46:35.463'),(15,'离子键','阴、阳离子之间通过静电作用所形成的化学键叫做离子键。','活泼金属与活泼非金属易形成离子键。','判断离子化合物时。','看是否由阴、阳离子构成；典型如NaCl。','NaCl、MgO、CaF2。','认为含金属就一定是离子化合物（如AlCl3有共价成分，高中以课本结论为准）。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.ionic_bond]',2,2,NULL,NULL,'2026-10-18 11:38:21.510','2026-10-18 20:46:35.465'),(16,'共价键','原子间通过共用电子对所形成的化学键叫做共价键。','非金属原子间常形成共价键。','单质分子与共价化合物。','看是否共用电子对；如H2、Cl2、H2O、CO2。','H—H，H—O，C=O。','把离子化合物中的化学式当作分子式乱画电子式。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.covalent_bond]',2,2,NULL,NULL,'2026-10-18 11:38:21.570','2026-10-18 20:46:35.465'),(17,'化学反应速率','化学反应速率表示反应进行的快慢。','受浓度、温度、压强（气体）、催化剂、接触面积等影响。','定性了解影响因素（必修层面）。','升温一般加快；催化剂改变化学反应速率。','块状锌与粉末锌和酸反应快慢不同。','把催化剂当成改变反应限度的因素。','pending_review','[inv:concept.reaction_rate]',2,2,NULL,NULL,'2026-10-18 11:38:21.611','2026-10-18 11:38:21.611'),(18,'化学反应限度','可逆反应进行的程度（限度）与反应速率是不同概念；限度讨论反应能进行到什么程度。','催化剂一般不改变化学平衡时的限度（高中初步）。','可逆反应初步认识。','区分“快慢”与“进行程度”。','合成氨反应可逆，存在限度。','把速率与转化率混为一谈。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.reaction_extent]',2,2,NULL,NULL,'2026-10-18 11:38:21.660','2026-10-18 20:46:35.466'),(19,'质量守恒定律','参加化学反应的各物质的质量总和等于反应后生成的各物质的质量总和。','反应前后原子种类与数目不变。','一切化学反应（忽略相对论质量等）。','配平方程式后检查原子个数。','2H2+O2=2H2O。','把“体积守恒”当成质量守恒。','pending_review','[inv:concept.mass_conserve]',2,2,NULL,NULL,'2026-10-18 11:38:21.693','2026-10-18 11:38:21.693'),(20,'电荷守恒','电荷守恒：在化学反应或电解质溶液中，正负电荷的代数和守恒（代数和为零或不改变）。','离子方程式配平必须检查电荷代数和相等，不能只数“离子个数”。','离子方程式、氧化还原配平。','检查离子方程式左右电荷代数和。','2H++CO32-=CO2↑+H2O。','只顾原子守恒不顾电荷守恒。','pending_review','[inv:concept.charge_conserve] B2整改:改为电荷代数和表述',2,2,NULL,NULL,'2026-10-18 11:38:21.727','2026-10-18 12:15:36.728'),(21,'电子守恒','氧化还原反应中，还原剂失电子总数等于氧化剂得电子总数。','电子转移守恒是配平依据之一。','氧化还原反应。','计算化合价升降总数使之相等。','MnO2与浓盐酸制Cl2时电子守恒。','只配平原子不配平电子得失。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.electron_conserve]',2,2,NULL,NULL,'2026-10-18 11:38:21.786','2026-10-18 20:46:35.466'),(22,'溶液与胶体','分散系按分散质粒子大小大致分为溶液、胶体、浊液；胶体粒子直径约在1–100 nm。','胶体有丁达尔效应等特性（高中了解）。','分散系分类。','粒子大小；丁达尔效应鉴别溶液与胶体。','NaCl溶液；Fe(OH)3胶体；泥水是浊液。','用能否透过滤纸区分胶体与溶液（两者一般都能透过）。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.solution_colloid]',2,2,NULL,NULL,'2026-10-18 11:38:21.828','2026-10-18 20:46:35.466'),(23,'酸碱盐概念','酸电离时生成的阳离子全部是H+；碱电离时生成的阴离子全部是OH-；盐由金属阳离子（或铵根）与酸根离子构成。','用电离观点定义更准确。','酸碱盐判断与命名。','看电离产物；注意酸式盐、碱式盐。','H2SO4是酸；NaOH是碱；Na2CO3是盐；NaHCO3是酸式盐。','认为含氧就一定是酸；把Na2O当成盐。','pending_review','[inv:concept.acid_base_salt]',2,2,NULL,NULL,'2026-10-18 11:38:21.876','2026-10-18 11:38:21.876'),(24,'氧化物分类','氧化物是由两种元素组成且其中一种是氧元素的化合物；可分为酸性、碱性、两性、不成盐氧化物等（高中常用分类）。','看氧化物对应水化物的酸碱性及与酸碱反应情况。','常见氧化物归类。','CO2是酸性氧化物；Na2O是碱性氧化物；Al2O3是两性氧化物；CO是不成盐氧化物。','见上。','把H2O、Na2O2简单当成普通氧化物而不加说明（过氧化物氧气价为-1）。','pending_review','[inv:concept.oxide_class]',2,2,NULL,NULL,'2026-10-18 11:38:21.910','2026-10-18 11:38:21.910'),(25,'合金','合金是由两种或两种以上的金属（或金属与非金属）熔合而成的具有金属特性的物质，一般属于混合物。','合金的性能通常与其组成和结构有关。与组成它的纯金属相比，许多常见合金的硬度更大，熔点往往较低；抗腐蚀性等也可能改善，但须看具体合金种类。不能将所有合金概括为具有相同性质，不得使用“所有合金硬度都更大”“所有合金熔点都更低”等绝对化表述。','讨论金属材料组成与性能比较时（必修金属材料部分）。','看是否由多种金属（或金属与非金属）熔合且具金属特性；纯金属单质不是合金；注意合金一般是混合物，无固定化学式。','生铁、钢、黄铜、不锈钢、镁铝合金等。','把合金当成纯净物或化合物；认为所有合金熔点一定更高或一定更低；用“一定更硬”绝对化而不看具体种类。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.alloy] B3整改P0:熔点/硬度分述;禁绝对化',2,2,NULL,NULL,'2026-10-18 12:59:27.651','2026-10-18 20:46:35.494'),(26,'可逆反应','在同一条件下，既能向生成物方向进行、同时又能向反应物方向进行的反应，叫做可逆反应；常用可逆箭头“⇌”表示。','可逆反应不能进行到底，存在一定的反应限度；反应速率描述快慢，限度描述进行程度，二者不同（与 concept.reaction_extent 互补）。','必修认识可逆反应与限度的初步概念；不要求选修化学平衡定量计算。','看是否在同一条件下正逆反应同时进行；书写是否用⇌；能否用“完全反应”简单描述。','合成氨 N2+3H2⇌2NH3；氯气与水 Cl2+H2O⇌HCl+HClO（教材常见）。','把加热、加压等不同条件下的正逆分步反应都叫可逆；混淆反应速率与反应限度；默认所有反应都可逆。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.reversible] 与 concept.reaction_extent 互补；禁选修计算默认训练',2,2,NULL,NULL,'2026-10-18 14:12:32.826','2026-10-18 20:46:35.748'),(27,'同系物','结构相似、分子组成上相差一个或若干个CH2原子团的有机物互称为同系物；同系物通式相同（如烷烃CnH2n+2）。','同系物化学性质相似，物理性质随碳原子数增加呈规律变化（教材定性认识）。','比较须结构相似且通式一致；官能团种类与数目须对应（高一常见：烷烃、烯烃等）。','看结构是否相似、组成差是否为n个CH2、通式是否相同。','CH4、C2H6、C3H8为同系物；CH2=CH2与CH3CH=CH2为同系物（烯烃）。','仅看分子式相差CH2就判同系物而忽略结构不相似；把同分异构体当成同系物。','pending_review','[inv:concept.homolog] batch6导入 pending_review id=27',2,2,NULL,NULL,'2026-10-18 17:05:42.023','2026-10-18 18:46:27.000'),(28,'同分异构体','分子式相同、结构不同的化合物互为同分异构体。','分子式相同而原子连接方式或官能团位置等不同，导致性质可能不同。','高一以碳链异构、位置异构等基础书写为主；复杂立体异构、大量推断限默认训练。','先确认分子式相同，再比较结构是否不同；可用结构简式列举。','C4H10的正丁烷与异丁烷；乙醇与二甲醚（分子式C2H6O，了解级示例以教材为准）。','把同系物当成同分异构体；重复书写同一结构；漏写或超纲展开。','pending_review','[inv:concept.isomer] 高一书写技能有限;复杂推断限默认训练',2,2,NULL,NULL,'2026-10-18 17:05:42.121','2026-10-18 18:46:27.000'),(29,'官能团初步','决定有机化合物主要化学性质的原子或原子团，叫做官能团。','相同官能团的化合物往往表现相似的化学性质；学习有机物常抓住官能团。','必修常见：碳碳双键、羟基、羧基、酯基等；深度以教材为准。','从结构简式中识别官能团，并联系典型反应（加成、酯化、酸性等）。','乙烯含碳碳双键；乙醇含羟基；乙酸含羧基；乙酸乙酯含酯基。','把碳碳单键或甲基当成官能团；混淆羟基与羧基。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.functional_group] batch6导入 pending_review id=29',2,2,NULL,NULL,'2026-10-18 17:05:42.319','2026-10-18 20:46:35.754'),(30,'取代反应','有机物分子中的某些原子或原子团被其他原子或原子团所替代的反应，叫做取代反应。','取代不是简单“丢掉”，而是一种原子/基团被另一种替代；甲烷氯代是典型例子。','烷烃光照氯代等；注意可生成多种取代产物。','看是否有原子/基团被替代，并生成相应小分子（如HCl）。','CH4与Cl2光照取代；苯的溴代等属更深层次，勿默认超纲。','把加成当成取代；把甲烷氯代写成只有一种产物。','pending_review','[inv:concept.substitution] batch6导入 pending_review id=30',2,2,NULL,NULL,'2026-10-18 17:05:42.417','2026-10-18 18:46:29.000'),(31,'加成反应','有机物分子中不饱和键两端的原子与其他原子或原子团直接结合生成新化合物的反应，叫做加成反应。','不饱和键（如双键）断裂π键，试剂两部分分别加到不饱和碳上。','烯烃与Br2、H2、H2O等；条件因试剂而异。','不饱和键数目减少、原子利用率高、常使溴水褪色等。','乙烯与溴、乙烯加氢、乙烯水化。','与取代混淆；误以为加成一定需要光照。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.addition] batch6导入 pending_review id=31',2,2,NULL,NULL,'2026-10-18 17:05:42.518','2026-10-18 20:46:35.754'),(32,'酯化反应规律','酸与醇反应生成酯和水的反应叫做酯化反应；乙酸与乙醇酯化是典型。','教材规律：酯化时羧酸提供羟基（−OH），醇提供羟基上的氢（−H），结合成水，其余部分结合成酯；反应可逆，常用浓硫酸催化并加热。','浓硫酸、加热；可逆，注意产率与分离。','反应物为酸+醇，产物为酯+水，条件含浓硫酸加热，箭头用⇌。','CH3COOH+C2H5OH⇌CH3COOC2H5+H2O','写成不可逆；漏写浓硫酸或加热；酸醇脱水部位记反（按教材规律记忆）。','pending_review','[inv:concept.esterification_rule] batch6导入 pending_review id=32',2,2,NULL,NULL,'2026-10-18 17:05:42.694','2026-10-18 18:46:30.000'),(33,'吸热反应','吸收热量的化学反应叫做吸热反应。','反应热效应取决于断键吸收能量与成键放出能量的相对大小：断键吸能、成键放能；若总效果为体系从环境吸热，则为吸热。加热只是反应条件，不等于该反应一定是吸热反应。','判断依据是反应的热效应，不是是否需要加热启动。','看ΔH符号或题给“吸热/放热”；不能仅凭“需要加热”判定为吸热。','某些分解反应（题设）；以教材列举为准。','把“需要加热”等同于吸热反应；忽略断键/成键能量比较。','pending_review','[inv:concept.endothermic] 加热≠吸热判据;断键吸能成键放能',2,2,NULL,NULL,'2026-10-18 17:05:42.768','2026-10-18 18:46:30.000'),(34,'放热反应','放出热量的化学反应叫做放热反应。','成键放出的总能量大于断键吸收的总能量时，反应放热。燃烧、中和等多属放热，但仍须以题设或能量数据为准。加热≠吸热，同样“能发生”也不等于放热判据。','热效应判断；可与原电池、燃烧等综合。','ΔH<0或题干明确放热；结合键能/能量图定性（教材深度）。','燃料燃烧；酸碱中和（常见）。','认为凡是燃烧以外的反应都吸热；用是否加热反推热效应。','pending_review','[inv:concept.exothermic] 加热≠吸热判据;总热效应看相对大小',2,2,NULL,NULL,'2026-10-18 17:05:42.866','2026-10-18 18:46:31.000'),(35,'反应热','化学反应中放出或吸收的热量叫做反应热（概念级认识）；可用热化学方程式表示反应热与物质聚集状态的关系。','反应热与物质的聚集状态、计量数有关；燃烧热、中和热等为相关概念（了解）。定量计算深度以所用教材为准。','必修第二册概念级；复杂热量计算不作为默认高一训练。','识别热化学方程式中的ΔH与状态；区分吸热/放热符号口径（随教材）。','热化学方程式示例以教材为准；注明气、液、固状态。','忽略聚集状态；把反应热与温度变化简单等同；超纲定量。','pending_review','[inv:concept.heat_of_reaction] 待教材核实:verifyNeeded;概念级;禁复杂定量默认训练;curriculumScope:必修第二册',2,2,NULL,NULL,'2026-10-18 17:05:42.932','2026-10-18 18:46:31.000'),(36,'加成聚合','不饱和单体通过加成的方式互相结合成为高分子化合物的反应，叫做加成聚合反应（加聚）。','如乙烯加聚生成聚乙烯：nCH2=CH2 →催化剂等→ ┄[CH2−CH2]┄n（写法随教材）。','必修了解聚合物与单体关系；不展开复杂高分子工程。','由高分子链节推断单体；单体含不饱和键。','乙烯→聚乙烯。','缩聚与加聚混淆；链节与单体写错。','published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:concept.addition_polymer] 乙烯加聚示例;范围按必修了解',2,2,NULL,NULL,'2026-10-18 17:05:43.066','2026-10-18 20:46:35.842');
/*!40000 ALTER TABLE `chem_concepts` ENABLE KEYS */;
