LOCK TABLES `chem_knowledge_points` WRITE;
/*!40000 ALTER TABLE `chem_knowledge_points` DISABLE KEYS */;
INSERT INTO `chem_knowledge_points` VALUES (1,NULL,'氧化还原反应','氧化还原反应：有化合价升降（本质是电子转移）的反应。化合价升高、失电子→被氧化，该物质是还原剂；化合价降低、得电子→被还原，该物质是氧化剂。判断方法：看化合价是否变化，再找升/降对应还原剂/氧化剂。注意：氧化剂≠氧化产物，还原剂≠还原产物。属高一必修核心。',2,5,'published','[kp.redox] 最终整改:完善定义/升降/电子转移/氧化剂还原剂/判断',NULL,NULL,NULL,NULL,'2026-10-18 09:49:46.125','2026-10-18 12:26:18.523'),(2,1,'化合价变化','反应前后元素化合价升降',2,4,'published','',NULL,NULL,NULL,NULL,'2026-10-18 09:49:46.191','2026-10-18 09:49:46.191'),(3,1,'氧化剂判断','得电子、化合价降低的物质',2,4,'published','',NULL,NULL,NULL,NULL,'2026-10-18 09:49:46.191','2026-10-18 09:49:46.191'),(4,1,'还原剂判断','失电子、化合价升高的物质',2,4,'published','',NULL,NULL,NULL,NULL,'2026-10-18 09:49:46.191','2026-10-18 09:49:46.191'),(5,NULL,'钠的化学性质','钠的化学性质须分条件记忆，不可混为一谈：①与氧气：常温主要生成Na2O（表面变暗），点燃燃烧生成淡黄色Na2O2；②与水：2Na+2H2O=2NaOH+H2，现象浮、熔、游、响，溶液显碱性；③与酸：与H+反应更剧烈生成盐和H2（了解对比，禁止学生自行实验）；④与盐溶液：可置换活动性较弱金属离子（题设）。保存于煤油/石蜡油。易错：燃烧产物写成Na2O；忽视条件对产物的影响。',2,5,'published','[kp.Na.property] B3整改:分条件写与O2/水/酸/盐;非人工审核',NULL,NULL,NULL,NULL,'2026-10-18 09:49:46.275','2026-10-18 13:12:15.000'),(6,1,'氧化产物判断','氧化产物是还原剂被氧化后的产物（化合价升高后的产物）。判断：找化合价升高的元素，其对应产物为氧化产物。例：2Na+Cl2=2NaCl中，NaCl对钠而言是氧化产物。易错：把氧化剂当成氧化产物。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.redox.ox_product] parent=kp.redox',2,2,NULL,NULL,'2026-10-18 11:38:27.593','2026-10-18 20:46:35.470'),(7,1,'还原产物判断','还原产物是氧化剂被还原后的产物（化合价降低后的产物）。例：同上反应中NaCl对氯而言是还原产物。易错：名称对调。',2,4,'pending_review','[inv:kp.redox.re_product] parent=kp.redox',2,2,NULL,NULL,'2026-10-18 11:38:27.672','2026-10-18 11:38:31.000'),(8,1,'电子转移','氧化还原的本质是电子转移（或共用电子对偏移）。可用双线桥/单线桥表示电子转移方向与数目。易错：只看氧元素是否参加。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.redox.e_transfer] parent=kp.redox',2,2,NULL,NULL,'2026-10-18 11:38:27.772','2026-10-18 20:46:35.470'),(9,1,'电子守恒','电子守恒：失电子总数=得电子总数，用于配平与计算。易错：只配平原子个数。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.redox.e_conserve] parent=kp.redox',2,2,NULL,NULL,'2026-10-18 11:38:27.887','2026-10-18 20:46:35.470'),(10,NULL,'电解质与非电解质','电解质：在水溶液中或熔融状态下能够导电的化合物。非电解质：在上述条件下都不能导电的化合物。注意：单质（如金属、石墨）既不是电解质也不是非电解质；二氧化碳、二氧化硫等本身是非电解质，其水溶液导电是因与水反应生成了电解质。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.ion.electrolyte] B2整改:补完整定义与单质边界',2,2,NULL,NULL,'2026-10-18 11:38:27.955','2026-10-18 20:46:35.471'),(11,NULL,'电离方程式书写','电离方程式书写：强电解质完全电离用“=”，弱电解质用“⇌”；注意原子守恒与电荷守恒；多元弱酸分步电离。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.ion.ionization_eq]',2,2,NULL,NULL,'2026-10-18 11:38:28.022','2026-10-18 20:46:35.471'),(12,NULL,'离子共存判断','离子共存：检查沉淀、气体、水、氧化还原、弱电解质生成。注意题设酸碱性与颜色。',3,5,'pending_review','[inv:kp.ion.coexist]',2,2,NULL,NULL,'2026-10-18 11:38:28.114','2026-10-18 11:38:28.114'),(13,NULL,'离子方程式书写','离子方程式：强电解质（易溶强酸强碱盐）拆成离子，沉淀、气体、弱电解质、单质、氧化物等不拆；删去旁观离子；检查原子守恒与电荷守恒。边界：微溶物是否拆、酸式盐拆分、少量/过量反应产物，以题设与课本规则为准，不可僵化。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.ion.ionic_eq] B2整改:补微溶/过量/酸式盐边界提示',2,2,NULL,NULL,'2026-10-18 11:38:28.197','2026-10-18 20:46:35.472'),(14,NULL,'原子组成与三粒子','原子组成：质子数=核电荷数=原子序数；质量数 A = 质子数 Z + 中子数 N（定义用等号，不是近似）；核外电子数=质子数（原子）。注意：质量数是整数，相对原子质量是加权平均值，二者不可混淆。离子的电子数随所带电荷变化。',1,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.structure.atom] | P0fix:质量数改用A=Z+N等号，区分相对原子质量',2,2,NULL,NULL,'2026-10-18 11:38:28.310','2026-10-18 20:46:35.472'),(15,NULL,'核素与同位素','核素：具有一定质子数和中子数的原子；同位素：质子数相同中子数不同的同一元素不同核素。化学性质几乎相同。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.structure.isotope]',2,2,NULL,NULL,'2026-10-18 11:38:28.380','2026-10-18 20:46:35.472'),(16,NULL,'化学键类型判断','离子键与共价键判断：活泼金属+活泼非金属倾向离子键；非金属之间倾向共价键。结合物质类别综合判断。',2,4,'pending_review','[inv:kp.structure.bond]',2,2,NULL,NULL,'2026-10-18 11:38:28.510','2026-10-18 11:38:28.510'),(17,NULL,'电子式书写','电子式：用“·”表示原子最外层电子。简单阳离子（如Na⁺、Ca²⁺）一般只写离子符号不画电子；阴离子与复杂阳离子（如NH₄⁺）需按规定画出电子式并标注电荷/括号。',3,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.structure.electron_formula] B2整改:区分简单/复杂阳离子',2,2,NULL,NULL,'2026-10-18 11:38:28.563','2026-10-18 20:46:35.473'),(18,NULL,'周期与族定位','周期数=电子层数；主族序数=最外层电子数（主族）。由原子序数推电子排布再定位。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.periodic.position]',2,2,NULL,NULL,'2026-10-18 11:38:28.647','2026-10-18 20:46:35.473'),(19,NULL,'核外电子排布','核外电子排布：先内后外，每层最多2n^2；最外层不超过8，次外层不超过18（高中规则）。',2,5,'pending_review','[inv:kp.periodic.e_config]',2,2,NULL,NULL,'2026-10-18 11:38:28.713','2026-10-18 11:38:28.713'),(20,NULL,'周期律递变规律','同周期（从左到右，主族）：金属性减弱、非金属性增强，原子半径一般减小，最高正化合价与族序相关。同主族（从上到下）：金属性增强、非金属性减弱，原子半径增大。比较方法：与水/酸反应难易、最高价氧化物对应水化物酸碱性、气态氢化物稳定性、单质氧化性等（限主族教学口径）。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.periodic.trend] B2整改:补具体递变方向与比较方法',2,2,NULL,NULL,'2026-10-18 11:38:28.780','2026-10-18 20:46:35.473'),(21,NULL,'物质的量三公式','物质的量三公式：n=m/M；n=N/NA；仅当气体处于标准状况时可用 n=V/22.4（V单位L）。先判断已知量与条件再选式；非标况气体不可用22.4。',1,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.calc.amount] B2整改:强调非标况不可用22.4',2,2,NULL,NULL,'2026-10-18 11:38:28.863','2026-10-18 20:46:35.474'),(22,NULL,'物质的量浓度','c=n/V，注意溶液体积单位为L；与质量分数、密度换算要分步。',2,5,'pending_review','[inv:kp.calc.concentration]',2,2,NULL,NULL,'2026-10-18 11:38:28.930','2026-10-18 11:38:28.930'),(23,NULL,'稀释计算','稀释前后溶质n不变：c1V1=c2V2。混合若反应则不能直接套用。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.calc.dilution]',2,2,NULL,NULL,'2026-10-18 11:38:28.997','2026-10-18 20:46:35.474'),(24,NULL,'常见化合价速记','常见化合价速记：K/Na +1；Ca/Mg/Ba/Zn +2；Al +3；Fe +2/+3；Cu +1/+2；H 多为+1（氢化物中可为−1）；F −1；O 通常−2（过氧化物中为−1）；Cl 常见−1；N 常见−3/+2/+4/+5（及+1/+3等）。注意硝酸等含氮化合物价态需按规则计算。',1,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.memory.valence_table] B2整改:补Fe/Cu/H等变价',2,2,NULL,NULL,'2026-10-18 11:38:29.080','2026-10-18 20:46:35.474'),(25,NULL,'常见离子速记','常见离子速记：NH₄⁺、OH⁻、NO₃⁻、SO₄²⁻、CO₃²⁻、Cl⁻、S²⁻、Ba²⁺、Ag⁺、Fe²⁺、Fe³⁺、Cu²⁺、Al³⁺等；电荷写在右上角。检验与共存题常考上述离子。',1,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.memory.ion_table] B2整改:补Fe²⁺/Ag⁺/S²⁻等',2,2,NULL,NULL,'2026-10-18 11:38:29.147','2026-10-18 20:46:35.475'),(26,NULL,'物质颜色速记','必修常见颜色：Cl₂黄绿；Br₂深红棕；I₂紫黑；Cu²⁺溶液蓝色；Fe²⁺溶液浅绿；Fe³⁺溶液黄/棕黄；Fe(OH)₂白色（易氧化）；Fe(OH)₃红褐；Cu(OH)₂蓝色。MnO₄⁻紫红偏拓展，训练中宜标注了解/非默认必修表。',2,3,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.memory.color_table] B2整改:补卤素与Fe²⁺，MnO₄⁻标拓展',2,2,NULL,NULL,'2026-10-18 11:38:29.238','2026-10-18 20:46:35.475'),(27,NULL,'钠的氧化物与过氧化物','钠常温与O2主要生成Na2O（白色）；燃烧生成Na2O2（淡黄色）。Na2O是碱性氧化物，与水生成NaOH。Na2O2中氧为−1价，与H2O、CO2反应都放出O2，常作供氧剂理解。易错：把燃烧产物写成Na2O；混淆氧化钠与过氧化钠的颜色与氧的化合价。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Na.oxide] batch3导入 pending_review id=27',2,2,NULL,NULL,'2026-10-18 12:59:26.054','2026-10-18 20:46:35.489'),(28,NULL,'碳酸钠与碳酸氢钠','Na2CO3（纯碱）热稳定性强；NaHCO3（小苏打）受热易分解生成Na2CO3、CO2、H2O。二者都能与酸放CO2。Na2CO3溶液通足量CO2可转化为NaHCO3。鉴别可用加热法或滴酸快慢/现象结合题设。易错：写错分解方程式计量数；忽略CO2用量对产物的影响。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Na.carbonate] batch3导入 pending_review id=28',2,2,NULL,NULL,'2026-10-18 12:59:26.263','2026-10-18 20:46:35.490'),(29,NULL,'铝及其化合物的两性','Al、Al2O3、Al(OH)3都能与强酸、强碱反应。Al与NaOH溶液反应放H2并生成偏铝酸盐。Al(OH)3加酸或过量强碱沉淀均溶解，是两性核心证据。溶液中偏铝酸根常写[Al(OH)4]-（了解）。易错：认为只有Al(OH)3两性而忽略Al与Al2O3；把Mg(OH)2也当成可溶于过量NaOH。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Al.amphoteric] batch3导入 pending_review id=29',2,2,NULL,NULL,'2026-10-18 12:59:26.351','2026-10-18 20:46:35.490'),(30,NULL,'铁的化学性质','铁可与O2点燃生成Fe3O4；与稀酸生成Fe2+盐与H2；能置换活动性较弱的金属离子。潮湿空气中易生锈。铁在反应中常见+2、+3价。易错：铁与稀酸写生成Fe3+；点燃产物写成Fe2O3。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Fe.property] batch3导入 pending_review id=30',2,2,NULL,NULL,'2026-10-18 12:59:26.466','2026-10-18 20:46:35.490'),(31,NULL,'金属活动性顺序','金属活动性顺序可用于判断：金属与酸/水反应难易、置换反应能否发生、盐溶液中金属与离子反应方向等。顺序越靠前越活泼。教材常见顺序（以课本为准）：K Ca Na Mg Al Zn Fe Sn Pb (H) Cu Hg Ag Pt Au。易错：用金属硬度、熔点直接代替活动性；忽略氢前氢后金属与酸反应差异。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.metal.activity] batch3导入 pending_review id=31',2,2,NULL,NULL,'2026-10-18 12:59:26.551','2026-10-18 20:46:35.491'),(32,NULL,'金属冶炼思路','冶炼本质是把化合态金属还原为单质。活泼金属常用电解法（如熔融Al2O3炼铝，了解）；较不活泼可用热还原（CO、C、H2等还原氧化物，如炼铁）；更不活泼可热分解等。易错：把所有金属都写成同一种冶炼方法。',3,4,'pending_review','[inv:kp.metal.smelting] batch3导入 pending_review id=32',2,2,NULL,NULL,'2026-10-18 12:59:26.649','2026-10-18 13:12:14.000'),(33,NULL,'Fe2+的性质','Fe2+水溶液常呈浅绿色，具还原性，易被氧化为Fe3+。与碱生成白色Fe(OH)2，在空气中迅速变灰绿最终红褐。可用氧化后再加KSCN的方法间接检验。易错：把Fe2+溶液颜色说成黄色；忽略隔绝空气保存。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Fe.fe2_property] 增补；还原性、浅绿色水溶液等; batch3导入 pending_review id=33',2,2,NULL,NULL,'2026-10-18 12:59:26.766','2026-10-18 20:46:35.492'),(34,NULL,'Fe3+的性质','Fe3+水溶液常呈黄至棕黄色，具一定氧化性；与碱生成红褐色Fe(OH)3；与KSCN呈血红色。可氧化I-、S2-等（了解/题设，不进默认基础训练）。易错：与Fe2+颜色、沉淀颜色混淆。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Fe.fe3_property] 增补；氧化性、黄色/棕黄色溶液等; batch3导入 pending_review id=34',2,2,NULL,NULL,'2026-10-18 12:59:26.851','2026-10-18 20:46:35.492'),(35,NULL,'Fe2+与Fe3+的转化','Fe2+可被适当氧化剂氧化为Fe3+；Fe3+可被适当还原剂还原为Fe2+，须写明具体试剂与条件，不可省略。必修核心示例：Fe2+→Fe3+可用Cl2、空气中O2等；Fe3+→Fe2+可用Fe、Cu等（按教材例）。酸性KMnO4、H2O2、I-等作了解/题设试剂，不进默认基础训练。易错：氧化剂与还原剂、氧化产物与还原产物对调；离子方程式不守恒。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Fe.fe2_fe3] B3整改:核心剂与了解剂分开;排除未标记深剂默认训练',2,2,NULL,NULL,'2026-10-18 12:59:26.966','2026-10-18 20:46:35.493'),(36,NULL,'Fe2+与Fe3+的检验','Fe3+：KSCN血红色；加碱红褐色沉淀。Fe2+：加碱白色沉淀并变色；先加KSCN无明显血红，再加氧化剂后变血红。注意排除干扰与题设条件。易错：直接对Fe2+加KSCN就报阳性。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Fe.test] 增补；KSCN、碱沉淀颜色等；实验细节见 exp.Fe3_SCN; batch3导入 pending_review id=36',2,2,NULL,NULL,'2026-10-18 12:59:27.182','2026-10-18 20:46:35.493'),(37,NULL,'亚铁盐与铁盐','亚铁盐含Fe2+（如FeSO4，溶液浅绿，还原性）；铁盐含Fe3+（如FeCl3，溶液黄/棕黄，氧化性更强）。保存亚铁盐常需防氧化。易错：两类盐性质混记；忽视水解酸性。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Fe.salt] 增补；概括两类盐；代表物见 sub.FeSO4 / sub.FeCl3; batch3导入 pending_review id=37',2,2,NULL,NULL,'2026-10-18 12:59:27.249','2026-10-18 20:46:35.493'),(38,NULL,'生铁','生铁是铁碳合金，含碳量高于钢（了解）。质硬而脆，可铸不可锻（了解）。用于铸造等。含碳量具体数值以所用教材为准（常见资料约2%–4.3%，待核实），默认基础训练不考具体百分数。易错：把生铁当成纯铁；与钢含碳量说反。',1,3,'pending_review','[inv:kp.metal.pig_iron] 了解级;含碳量待教材核实;排除默认百分数题',2,2,NULL,NULL,'2026-10-18 12:59:27.334','2026-10-18 13:12:15.000'),(39,NULL,'钢','钢是含碳量低于生铁的铁碳合金（了解）。具有良好的塑性和强度，可锻造轧制。通过调整成分与处理获得不同性能。含碳量具体数值以所用教材为准（常见资料约0.03%–2%，待核实），默认基础训练不考具体百分数。易错：认为钢是纯净物；与生铁含碳量说反。',1,3,'pending_review','[inv:kp.metal.steel] 了解级;含碳量待教材核实;排除默认百分数题',2,2,NULL,NULL,'2026-10-18 12:59:27.432','2026-10-18 13:12:15.000'),(40,NULL,'不锈钢','不锈钢是加入铬等元素提高抗腐蚀能力的钢（了解级，不进默认高一核心训练池）。日常器皿常用。勿展开铬酸盐深度氧化还原。易错：以为不锈钢绝对不锈、永不腐蚀。',1,2,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.metal.stainless] 了解级;排除默认核心训练',2,2,NULL,NULL,'2026-10-18 12:59:27.499','2026-10-18 20:46:35.495'),(41,NULL,'铝盐与偏铝酸盐转化','Al3+加适量碱得Al(OH)3，碱过量转化为AlO2-（高中简化）或[Al(OH)4]-（了解/待核实）；向偏铝酸盐溶液加酸先沉淀后溶解。双向转化体现两性，常考图像题与离子共存。命题须指定离子写法。易错：酸碱过量不足导致沉淀量分析错误。',3,5,'pending_review','[inv:kp.Al.salt_aluminate] 待核实:AlO2-与[Al(OH)4]-口径',2,2,NULL,NULL,'2026-10-18 12:59:27.565','2026-10-18 13:12:15.000'),(42,NULL,'氯气的性质与用途','Cl2黄绿色有毒气体，强氧化性：与H2、金属、水、碱等反应须分条件。氯水成分为混合物（Cl2、H2O、HCl、HClO等）。漂白看HClO。用途：消毒漂白等（了解）。易错：把干燥Cl2直接当成漂白；忽略可逆与歧化。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Cl.property] batch4导入 pending_review id=42',2,2,NULL,NULL,'2026-10-18 13:26:57.859','2026-10-18 20:46:35.602'),(43,NULL,'氯气的实验室制取','实验室常用MnO2与浓盐酸加热：MnO2+4HCl(浓)=△=MnCl2+Cl2↑+2H2O。向上排空气法收集，NaOH吸收尾气。易错：用稀盐酸；忘记尾气处理；收集方法错误。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Cl.prep] batch4导入 pending_review id=43',2,2,NULL,NULL,'2026-10-18 13:26:58.124','2026-10-18 20:46:35.602'),(44,NULL,'硫的氧化物与硫酸','S燃烧得SO2；SO2催化氧化得SO3；SO3与水得H2SO4。SO2：酸性氧化物、还原性、漂白（可恢复）。浓硫酸：吸水、脱水、强氧化（加热）；稀硫酸强酸通性。易错：混写浓稀硫酸与铜反应；混淆SO2与Cl2漂白。',3,5,'pending_review','[inv:kp.S.oxide] batch4导入 pending_review id=44',2,2,NULL,NULL,'2026-10-18 13:26:58.385','2026-10-18 13:44:55.000'),(45,NULL,'氮及其化合物转化','重要转化：N2⇌NH3（合成氨条件了解）；NH3催化氧化→NO；NO→NO2；NO2与水→HNO3+NO；硝酸与铜因浓稀产物不同。氮氧化物与酸雨/污染了解。易错：NO与NO2颜色、转化条件混淆；浓稀硝酸方程式混用。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.N.cycle] batch4导入 pending_review id=45',2,2,NULL,NULL,'2026-10-18 13:26:58.486','2026-10-18 20:46:35.603'),(46,NULL,'氨的性质与制取','NH3刺激性、密度比空气小、极易溶于水显碱性。实验室：铵盐与碱共热。检验：湿润红色石蕊试纸变蓝；与HCl白烟。喷泉实验体现溶解性。易错：收集方法用错；忽视防倒吸。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.N.ammonia] batch4导入 pending_review id=46',2,2,NULL,NULL,'2026-10-18 13:26:58.618','2026-10-18 20:46:35.603'),(47,NULL,'碳的氧化物','CO：有毒、可燃、还原性，一般不使石灰水变浑浊。CO2：酸性氧化物，使石灰水变浑浊，一般不支持燃烧（镁例外）。碳燃烧产物随氧气是否充足为CO或CO2。易错：用石灰水检验CO；忽视CO毒性。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.C.oxide] batch4导入 pending_review id=47',2,2,NULL,NULL,'2026-10-18 13:26:58.703','2026-10-18 20:46:35.603'),(48,NULL,'硅与二氧化硅','Si是重要半导体材料（了解）。SiO2是原子晶体（了解表述）、酸性氧化物，与NaOH反应生成硅酸盐，故碱液腐蚀玻璃。粗硅可由SiO2与C高温制取（了解）。易错：认为SiO2与一般酸都反应；忽视玻璃腐蚀警示。',2,4,'pending_review','[inv:kp.Si.property] batch4导入 pending_review id=48',2,2,NULL,NULL,'2026-10-18 13:26:58.842','2026-10-18 13:44:59.000'),(49,NULL,'常见气体检验方法','H2：可燃，安静燃烧淡蓝火焰（验纯）。O2：带火星木条复燃。CO2：澄清石灰水变浑浊。Cl2：黄绿色；湿润淀粉KI试纸变蓝。NH3：湿润红色石蕊试纸变蓝；白烟。SO2：品红褪色加热恢复等。注意题设干扰与安全。易错：检验方法张冠李戴。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.nonmetal.test] batch4导入 pending_review id=49',2,2,NULL,NULL,'2026-10-18 13:26:58.976','2026-10-18 20:46:35.604'),(50,NULL,'浓硫酸的特性','浓硫酸三大特性：吸水性、脱水性、强氧化性（常需加热才显著表现氧化性，如与Cu、C）。稀硫酸主要表现为强酸通性，常温一般不氧化Cu。稀释：酸入水。易错：把稀硫酸当成强氧化性酸；稀释顺序颠倒。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.S.conc_H2SO4] 增补；吸水性、脱水性、强氧化性；与稀硫酸对比; batch4导入 pending_review id=50',2,2,NULL,NULL,'2026-10-18 13:26:59.167','2026-10-18 20:46:35.605'),(51,NULL,'铵盐的性质','铵盐与碱共热放NH3；某些铵盐受热可分解（如NH4Cl受热分解为NH3和HCl，冷却又结合，了解）。铵根检验：加碱加热，湿润红色石蕊试纸变蓝。易错：不加热就写放氨；与硝酸盐性质混淆。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.N.ammonium] 增补；受热分解、与碱反应等; batch4导入 pending_review id=51',2,2,NULL,NULL,'2026-10-18 13:26:59.292','2026-10-18 20:46:35.605'),(52,NULL,'卤族元素性质比较','卤族单质氧化性大致：F2>Cl2>Br2>I2；卤化氢稳定性大致HF>HCl>HBr>HI（以课本为准）。置换：Cl2可置换Br-、I-等（题设）。深度含氧酸体系标了解，不进默认核心。易错：递变顺序记反；把含氧酸深度当必修默认。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.halogen.compare] 深度含氧酸了解;勿超纲默认训练',2,2,NULL,NULL,'2026-10-18 13:26:59.434','2026-10-18 20:46:35.741'),(53,NULL,'合成氨反应条件与可逆性','N2+3H2⇌2NH3（催化剂、高温、高压）。高一认识：需要条件、反应可逆、工业意义。不要写成选修化学平衡定量计算或勒夏特列深度训练默认题。挂接反应条rxn.N2_3H2。易错：写成常温即可大量合成；忽略可逆。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.N.synth_ammonia] 勿选修平衡定量默认训练',2,2,NULL,NULL,'2026-10-18 13:26:59.535','2026-10-18 20:46:35.742'),(54,NULL,'氯水与漂白原理','新制氯水含HClO而有漂白性；久置氯水HClO分解，漂白性减弱，主要剩盐酸。干燥Cl2通常无漂白性。与SO2漂白对比：HClO漂白不可逆（有色物质被氧化），SO2漂白加热可恢复。易错：认为Cl2分子直接漂白；混淆两种漂白。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.Cl.bleach] 增补；次氯酸漂白；与 SO2 漂白对比见 batch4 实验; batch4导入 pending_review id=54',2,2,NULL,NULL,'2026-10-18 13:26:59.618','2026-10-18 20:46:35.742'),(55,NULL,'化学方程式计算步骤','一般步骤：写对并配平方程式→理清已知与待求→将质量/体积等换算为n（气体仅在标况用22.4）→按计量数关系列比例→回代单位作答。有纯度、产率、过量时先处理实际反应的量。易错：未配平；用质量比直接当计量比。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.calc.stoich] batch5导入 pending_review id=55',2,2,NULL,NULL,'2026-10-18 14:11:36.867','2026-10-18 20:46:35.746'),(56,NULL,'过量问题分析方法','给出多种反应物用量时，先把各量化为n，用 n/计量数比较大小，小的为不足量，按不足量计算生成物；剩余量=过量投料−按不足量消耗。易错：不判断过量；剩余量算错。可与 formula.excess_reactant 对照训练。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.calc.excess] batch5导入 pending_review id=56',2,2,NULL,NULL,'2026-10-18 14:11:37.078','2026-10-18 20:46:35.747'),(57,NULL,'气体相关计算','气体物质的量与体积换算：仅当题目明确标准状况（标况，教材定义的0℃、101 kPa）时，才可用 Vm≈22.4 L/mol，即 V=n×22.4 L/mol。未指明标况、或非常温常压默认，都不得使用22.4。同温同压下气体体积比≈物质的量比（阿伏加德罗定律思想）。易错：任何温度压强都套22.4。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.calc.gas] Vm=22.4仅标况；禁非标况套用',2,2,NULL,NULL,'2026-10-18 14:11:37.345','2026-10-18 20:46:35.842'),(58,NULL,'溶液浓度综合','物质的量浓度 c=n/V，V为溶液体积（L）。稀释：溶质n不变，c1V1=c2V2（只加水）。勿与质量分数w=m溶质/m溶液混淆；密度换算见已有公式条目。配制与定容误差见实验误差知识点。易错：V用溶剂体积；百分浓度与mol/L混用。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.calc.solution] batch5导入 pending_review id=58',2,2,NULL,NULL,'2026-10-18 14:11:37.495','2026-10-18 20:46:35.843'),(59,NULL,'实验方案设计要点','书面评价实验方案：目的明确→原理可行→试剂与仪器匹配→步骤顺序合理（先气密性等）→现象可检验结论→安全与尾气/废液。比较方案时看是否干扰、是否可操作、是否过量或不足。本产品只做方案评价，不要求动手。',3,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.exp.design] batch5导入 pending_review id=59',2,2,NULL,NULL,'2026-10-18 14:11:37.622','2026-10-18 20:46:35.843'),(60,NULL,'实验误差分析','误差分析必须对应具体操作阶段与测定量，禁止脱离条件直接写“偏大/偏小”。以配制一定物质的量浓度溶液（c=n/V）为例（书面分析）：①洁净容量瓶内残留少量蒸馏水，随后按规范定容且无其他错误时，一般不改变溶质的物质的量n，也不改变最终溶液体积V，故c通常不变；②定容时俯视刻度线→读得V偏小→c偏大；仰视→V偏大→c偏小；③烧杯/玻璃棒未洗涤或洗涤液未转入→n偏小→c偏小；④溶解未冷却即定容→冷却后液面低于刻度→V偏小→c偏大；⑤定容摇匀后发现液面低于刻度又加水→V偏大且相当于稀释→c偏小；⑥超过刻度线后用胶头滴管吸出部分溶液→溶质与溶剂同时损失，n偏小→c通常偏小。过滤、称量、气体收集不纯等亦须先定位操作再谈影响。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.exp.error] B5整改:容量瓶分阶段对照;禁无阶段绝对偏向题',2,2,NULL,NULL,'2026-10-18 14:11:37.697','2026-10-18 20:46:35.843'),(61,NULL,'气体的洗涤与干燥','洗气除杂：选能反应或吸收杂质、尽量不吸收目标气体的试剂；注意气体通过顺序（如先除杂再干燥，避免干燥后再通入水溶液）。干燥剂选择：酸性/碱性/中性气体与浓硫酸、碱石灰、无水CaCl2等匹配（按教材常见组合）。装置：洗气瓶导管长进短出。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.exp.gas_wash_dry] 增补；试剂选择与顺序; batch5导入 pending_review id=61',2,2,NULL,NULL,'2026-10-18 14:11:37.856','2026-10-18 20:46:35.747'),(62,NULL,'影响化学反应速率的因素','必修层面定性认识：增大反应物浓度、升高温度、使用催化剂、增大固体接触面积等，一般可加快反应速率（见 concept.reaction_rate）。催化剂改变化学反应速率，不改变化学反应限度（与 concept.reaction_extent 区分）。易错：把催化剂当成提高产率/转化率的因素。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.rate.factors] 关联 concept.reaction_rate',2,2,NULL,NULL,'2026-10-18 14:11:38.056','2026-10-18 20:46:35.748'),(63,NULL,'化学反应限度与条件影响（定性）','可逆反应存在一定限度（转化不能按“进行到底”理解）。高一以定性认识为主：条件改变可能影响转化方向/限度的认识层次以所用必修教材为准；不把“勒夏特列原理”命名与选修化学平衡常数、复杂图像定量作为默认核心训练。禁止选修深度计算。',2,4,'pending_review','[inv:kp.extent.le_chatelier_basic] 待核实:教材深度与命名;仅极浅定性;excludeDefaultEquilibriumCalc',2,2,NULL,NULL,'2026-10-18 14:11:38.162','2026-10-18 16:49:33.000'),(64,NULL,'甲烷结构与性质','甲烷分子为正四面体结构，分子式CH4。性质稳定，可燃烧；光照下与氯气发生取代，产物可为多种氯代甲烷，不得写唯一产物。是认识烷烃的典型代表。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.organic.methane] batch6导入 pending_review id=64',2,2,NULL,NULL,'2026-10-18 17:06:06.323','2026-10-18 20:46:35.755'),(65,NULL,'烷烃通式与性质','烷烃通式CnH2n+2（链状），为饱和烃。化学性质较稳定，可发生取代与燃烧；一般不能因加成使溴水褪色。同系物物理性质递变。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.organic.alkane] batch6导入 pending_review id=65',2,2,NULL,NULL,'2026-10-18 17:06:06.412','2026-10-18 20:46:35.755'),(66,NULL,'乙烯结构与性质','乙烯结构简式CH2=CH2，含碳碳双键。易加成（Br2、H2、H2O等）；使酸性KMnO4褪色但不指定唯一氧化产物；可加聚。实验室可由乙醇浓硫酸加热制取（认知）。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.organic.ethene] batch6导入 pending_review id=66',2,2,NULL,NULL,'2026-10-18 17:06:06.493','2026-10-18 20:46:35.833'),(67,NULL,'乙醇结构与性质','乙醇CH3CH2OH，官能团羟基。可燃烧；Cu/Ag催化加热下氧化为乙醛；与乙酸酯化。物理性质：无色液体、与水互溶、易燃。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.organic.ethanol] batch6导入 pending_review id=67',2,2,NULL,NULL,'2026-10-18 17:06:06.590','2026-10-18 20:46:35.834'),(68,NULL,'乙酸结构与性质','乙酸CH3COOH，官能团羧基，弱酸但具酸通性；酸性强于碳酸（与碳酸盐放CO2）。可发生酯化。食醋中含乙酸（了解）。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.organic.acetic] batch6导入 pending_review id=68',2,2,NULL,NULL,'2026-10-18 17:06:06.648','2026-10-18 20:46:35.834'),(69,NULL,'同分异构体书写技能','先固定分子式，再按碳链异构、官能团位置等有序列举，检查重复与遗漏。高一以简单烷烃/烯烃/醇醚等基础题型为主，复杂推断不作为默认训练。',3,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.organic.isomer_skill] 高一基础书写;复杂推断限默认',2,2,NULL,NULL,'2026-10-18 17:06:06.785','2026-10-18 20:46:35.835'),(70,NULL,'颜色推断方法','利用物质或离子的特征颜色、溶液褪色/变色作为突破口：如酸性KMnO4紫红、溴水橙红、Cu2+蓝、Fe3+黄棕、沉淀颜色等。须结合题设试剂与条件，避免单一线索武断。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.inference.color] batch6导入 pending_review id=70',2,2,NULL,NULL,'2026-10-18 17:06:06.973','2026-10-18 20:46:35.835'),(71,NULL,'无机框图推断策略','框图推断：先找特征转化（气、沉淀、颜色、焰色、酸碱性），再确定突破口物质，最后用箭头关系验证全局自洽。注意过量与气体通入顺序对产物的影响。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.inference.block] batch6导入 pending_review id=71',2,2,NULL,NULL,'2026-10-18 17:06:07.060','2026-10-18 20:46:35.836'),(72,NULL,'物质转化推断','沿转化关系写可能反应类型（置换、复分解、氧化还原、有机加成/取代等），用计量与现象约束排除干扰。有机转化抓住官能团变化。',3,4,'pending_review','[inv:kp.inference.conversion] batch6导入 pending_review id=72',2,2,NULL,NULL,'2026-10-18 17:06:07.198','2026-10-18 18:46:36.000'),(73,NULL,'基础综合解题框架','综合题一般路径：审清已知与设问→定位知识模块（元素/有机/能量/实验）→写关键方程式或关系式→检查计量、条件与单位→回代题设验证。先易后难，避免跳步丢条件。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.comprehensive.basic] batch6导入 pending_review id=73',2,2,NULL,NULL,'2026-10-18 17:06:07.348','2026-10-18 20:46:35.836'),(74,NULL,'化学键与能量变化','化学反应中：断裂化学键吸收能量，形成化学键放出能量。反应吸热还是放热，取决于二者总效果的相对大小，不能仅凭是否加热判断。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.energy.bond_change] 增补；断键吸热、成键放热（中学口径）; batch6导入 pending_review id=74',2,2,NULL,NULL,'2026-10-18 17:06:07.509','2026-10-18 20:46:35.836'),(75,NULL,'化学能与电能','原电池等装置可把化学能转化为电能；电解则是电能转化为化学能（了解对比）。认识能量转化形式是必修要点。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.energy.chem_electric] 增补; batch6导入 pending_review id=75; B6整改:category redox.e_transfer→e_direction',2,2,NULL,NULL,'2026-10-18 17:06:07.768','2026-10-18 20:46:35.836'),(76,NULL,'原电池','原电池是将化学能转化为电能的装置。一般需：自发氧化还原反应、电极、电解质溶液（或离子导体）、形成闭合回路。电子在外电路迁移，离子在电解质中迁移。并非所有原电池都必须由两种不同金属构成，电极组合以题设与构成条件为准。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.energy.galvanic] B6整改:收窄专项去掉experiment主挂;电子外电路;离子在电解质;不必须两种不同金属',2,2,NULL,NULL,'2026-10-18 17:06:07.977','2026-10-18 20:46:35.837'),(77,NULL,'原电池正负极','负极：发生氧化反应（失电子），通常是较活泼金属电极。正极：发生还原反应（得电子）。正负极判断要结合电极材料与电解质中的氧化剂。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.energy.galvanic_poles] 增补; batch6导入 pending_review id=77',2,2,NULL,NULL,'2026-10-18 17:06:08.044','2026-10-18 20:46:35.837'),(78,NULL,'原电池电子流向','外电路中电子由负极流向正极；电流方向与电子流向相反。溶液中阳离子向正极迁移、阴离子向负极迁移，不可说电子在溶液中流动。',2,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.energy.electron_flow] 增补；外电路电子由负极到正极; batch6导入 pending_review id=78',2,2,NULL,NULL,'2026-10-18 17:06:08.132','2026-10-18 20:46:35.837'),(79,NULL,'原电池电极反应','分别写出负极氧化、正极还原的电极反应式，再相加得总反应。Zn-Cu原电池：电解质为CuSO4时正极多为Cu2+得电子；为稀H2SO4时正极多为H+得电子。须按题设书写。',3,5,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.energy.electrode_rxn] 增补; batch6导入 pending_review id=79',2,2,NULL,NULL,'2026-10-18 17:06:08.191','2026-10-18 20:46:35.837'),(80,NULL,'常见化学电源','了解常见化学电源（如干电池、蓄电池、锂电池等名称与用途层次，以教材为准）。勿展开复杂电化学工程与电极材料细节作为默认训练。',2,3,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.energy.chem_power] 了解级;勿展开工程细节',2,2,NULL,NULL,'2026-10-18 17:06:08.249','2026-10-18 20:46:35.838'),(81,NULL,'热化学方程式书写','热化学方程式须注明物质聚集状态，并给出ΔH（符号与单位口径随教材）。计量数与ΔH对应；同一反应计量数翻倍则ΔH相应变化。',3,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.energy.thermo_eq] 增补；注明物质聚集状态与ΔH 符号口径; batch6导入 pending_review id=81',2,2,NULL,NULL,'2026-10-18 17:06:08.335','2026-10-18 20:46:35.838'),(82,NULL,'海水资源开发','海水中含丰富水资源与化学资源（如NaCl、镁、溴等，了解）。认识海水淡化与综合利用的意义，深度以教材案例为准。',1,3,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.sustain.seawater] 增补; batch6导入 pending_review id=82',2,2,NULL,NULL,'2026-10-18 17:06:08.432','2026-10-18 20:46:35.839'),(83,NULL,'煤的综合利用','煤可通过干馏、气化、液化等途径综合利用（了解名称与意义），减少污染、提高资源利用率。勿展开复杂工艺计算。',2,3,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.sustain.coal] 增补; batch6导入 pending_review id=83',2,2,NULL,NULL,'2026-10-18 17:06:08.548','2026-10-18 20:46:35.839'),(84,NULL,'石油分馏','石油分馏是利用各组分沸点不同进行分离的物理变化过程，得到汽油、煤油、柴油等馏分（了解）。与裂化、裂解等化学加工区分。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.organic.petroleum] 增补；物理变化认识; batch6导入 pending_review id=84',2,2,NULL,NULL,'2026-10-18 17:06:08.634','2026-10-18 20:46:35.839'),(85,NULL,'石油裂化','裂化是使长链烃断裂为较短链烃的过程，以提高轻质燃油产量等（了解）。与裂解区分；具体反应深度与考法待教材核实。',2,3,'pending_review','[inv:kp.organic.cracking] 待教材核实:与裂解区分;深度待核实;excludeDefaultTrainingUntilVerified;非人工已审',2,2,NULL,NULL,'2026-10-18 17:06:08.701','2026-10-18 18:46:46.000'),(86,NULL,'石油裂解','裂解是深度断裂以获得乙烯、丙烯等化工原料的过程（了解）。与裂化目的与条件不同；细节待教材核实前不作默认核心训练。',2,3,'pending_review','[inv:kp.organic.pyrolysis] 待教材核实:与裂化区分;深度待核实;excludeDefaultTrainingUntilVerified;非人工已审',2,2,NULL,NULL,'2026-10-18 17:06:08.906','2026-10-18 18:46:47.000'),(87,NULL,'天然气利用','天然气主要成分为甲烷，是较清洁的化石燃料；也可作化工原料（了解）。注意安全使用与碳中和背景认知（教材层次）。',1,3,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.sustain.natural_gas] 增补; batch6导入 pending_review id=87',2,2,NULL,NULL,'2026-10-18 17:06:08.993','2026-10-18 20:46:35.840'),(88,NULL,'化肥合理使用','认识氮、磷、钾肥等作用与合理施用，避免过量导致污染。结合元素化合物知识作了解级综合。',1,3,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.sustain.fertilizer] 增补; batch6导入 pending_review id=88',2,2,NULL,NULL,'2026-10-18 17:06:09.059','2026-10-18 20:46:35.840'),(89,NULL,'农药合理使用','农药有助于防治病虫害，但须合理使用，减少残留与生态危害。属社会责任与科学态度类认知条目。',1,3,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.sustain.pesticide] 增补; batch6导入 pending_review id=89',2,2,NULL,NULL,'2026-10-18 17:06:09.126','2026-10-18 20:46:35.840'),(90,NULL,'药物合理使用','认识药物按说明书与医嘱使用的重要性，了解滥用抗生素等危害（教材案例层次），不涉及诊疗指导。',1,3,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.sustain.medicine] 增补; batch6导入 pending_review id=90',2,2,NULL,NULL,'2026-10-18 17:06:09.214','2026-10-18 20:46:35.840'),(91,NULL,'食品添加剂','食品添加剂在规定范围与剂量内可改善食品品质；应正确认识“合法合规使用”与安全，抵制非法添加。',1,3,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.sustain.food_additive] 增补；合理使用与安全认知; batch6导入 pending_review id=91',2,2,NULL,NULL,'2026-10-18 17:06:09.273','2026-10-18 20:46:35.841'),(92,NULL,'环境污染与防治认知','认识大气污染、水污染、土壤污染等类型及防治思路：源头控制、达标排放、绿色工艺与个人环保行为。结合硫氧化物、氮氧化物、塑料等教材案例。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.enviro.pollution] 增补; batch6导入 pending_review id=92',2,2,NULL,NULL,'2026-10-18 17:06:09.331','2026-10-18 20:46:35.841'),(93,NULL,'酸雨','酸雨主要与SO2、NOx等排放有关；可酸化水体与土壤、腐蚀建筑。防治：脱硫脱硝、清洁能源、节能等。与硫、氮氧化物知识综合。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.enviro.acid_rain] 增补；主知识在综合批；非金属批通过关联引用; batch6导入 pending_review id=93',2,2,NULL,NULL,'2026-10-18 17:06:09.418','2026-10-18 20:46:35.841'),(94,NULL,'绿色化学','绿色化学强调从源头减少或消除污染，提高原子利用率，选用更安全的原料、溶剂与反应路径（概念认识）。',2,4,'published','[ai_trial][human_unreviewed][trial_run][source:deepseek_r1] [inv:kp.sustain.green_chem] 增补; batch6导入 pending_review id=94',2,2,NULL,NULL,'2026-10-18 17:06:09.523','2026-10-18 20:46:35.842'),(95,NULL,'原子经济性','原子经济性关注反应物原子进入目标产物的比例，加成等反应原子利用率高（概念级）。定量计算公式与训练深度待教材核实。',2,3,'pending_review','[inv:kp.sustain.atom_economy] 待教材核实:概念级;计算题深度待核实;excludeDefaultTrainingUntilVerified;已去掉calculation.mixed默认关联;非人工已审',2,2,NULL,NULL,'2026-10-18 17:06:09.609','2026-10-18 18:46:52.000'),(96,NULL,'生命中的基本有机物（了解）','糖类、油脂、蛋白质、维生素等是生命中的基本有机物（认知级）。了解存在与功能层次即可，勿展开生物学详细代谢途径。',1,3,'pending_review','[inv:kp.organic.biomolecule] 待教材核实:覆盖深度;认知级;勿展开代谢;excludeDefaultTrainingUntilVerified;非人工已审',2,2,NULL,NULL,'2026-10-18 17:06:09.676','2026-10-18 18:46:52.000');
