/*!40000 ALTER TABLE `chem_questions` DISABLE KEYS */;
INSERT INTO `chem_questions` VALUES (1,'single','钠与水反应的生成物是？','[\"Na2O 和 H2\", \"NaOH 和 H2\", \"NaOH 和 O2\", \"Na2O2 和 H2\"]','NaOH 和 H2','钠与水发生置换反应：2Na+2H2O=2NaOH+H2↑','选对得满分',1,'published','',NULL,NULL,NULL,NULL,'2026-10-18 09:49:47.635','2026-10-18 09:49:47.635'),(2,'single','（骨架）标准状况下，11.2 L O2 的物质的量是多少？（选项示例：A.0.25 mol  B.0.5 mol  C.1 mol  D.2 mol）','[{\"key\": \"A\", \"text\": \"0.25 mol\"}, {\"key\": \"B\", \"text\": \"0.5 mol\"}, {\"key\": \"C\", \"text\": \"1 mol\"}, {\"key\": \"D\", \"text\": \"2 mol\"}]','B','标况 V=n×22.4，n=11.2/22.4=0.5 mol。非标况不可套用。','选对得分；须强调单位 mol 与标况条件。',1,'pending_review','[inv:q.calc.amount_basic] 骨架；可替换数据后充实为正式训练题 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 14:12:05.260','2026-10-18 19:27:38.794'),(3,'blank','（骨架）将 0.1 mol NaOH 溶于水并配成 500 mL 溶液，该溶液的物质的量浓度为______ mol/L。',NULL,'0.2','c=n/V=0.1 mol / 0.5 L=0.2 mol/L。注意 V 用溶液体积且换算为 L。','填数值；单位在题干已给时可不写，评分关注数值与单位一致性。',1,'pending_review','[inv:q.calc.concentration] 骨架；单位得分点：mol/L [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 14:12:05.378','2026-10-18 19:27:38.795'),(4,'calc','（骨架）已知 2H2+O2=2H2O。标准状况下 4.48 L H2 完全反应，生成水的质量为多少克？（写出计算过程）',NULL,'3.6 g（过程：n(H2)=4.48/22.4=0.2 mol；由计量关系生成 n(H2O)=0.2 mol；m=0.2×18=3.6 g）','先在标况下求 n，再按方程式计量比，最后 m=nM。','过程分+结果分；单位 g 必写；未说明标况却用22.4不得分。',2,'pending_review','[inv:q.calc.equation] 骨架；计算短答模板 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 14:12:05.556','2026-10-18 19:27:38.796'),(5,'calc','（骨架）反应：Zn + H2SO4 = ZnSO4 + H2↑（稀硫酸，不可逆按完全反应计，无副反应）。现有 Zn 13.0 g 与 H2SO4 0.15 mol 混合充分反应。已知 M(Zn)=65 g/mol。求生成 H2 的物质的量（单位 mol）。要求：先判断过量，再按不足量计算。',NULL,'0.15 mol（过程：n(Zn)=13.0/65=0.20 mol；计量数均为1，n(Zn)/1=0.20 > n(H2SO4)/1=0.15，故 H2SO4 不足；n(H2)=n(不足量)=0.15 mol）','先算 n(Zn) 与 n(H2SO4)，用 n/计量数比较；小者为不足量，按不足量得 n(H2)。本骨架条件唯一，禁止再混入第二组对照数据。','过量判断过程分+结果 0.15 mol；单位 mol 必写；未判断过量直接代算不得满分。',2,'pending_review','[inv:q.calc.excess] B5整改:单一数据组过量骨架;可作模板 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 14:12:05.795','2026-10-18 19:27:38.796'),(6,'single','（骨架）下列仪器中，不能用来加热的是？A.试管  B.烧杯  C.量筒  D.蒸发皿','[{\"key\": \"A\", \"text\": \"试管\"}, {\"key\": \"B\", \"text\": \"烧杯\"}, {\"key\": \"C\", \"text\": \"量筒\"}, {\"key\": \"D\", \"text\": \"蒸发皿\"}]','C','量筒用于量取液体体积，不可加热。烧杯加热需垫石棉网（按教材）。','选对得分。',1,'pending_review','[inv:q.exp.instrument] 骨架；仪器识别选择题模板 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 14:12:05.922','2026-10-18 19:27:38.797'),(7,'single','（骨架）实验室收集CO2常用的方法是？A.向下排空气法  B.向上排空气法  C.排水法（最佳首选）  D.向下排空气法并排水','[{\"key\": \"A\", \"text\": \"向下排空气法\"}, {\"key\": \"B\", \"text\": \"向上排空气法\"}, {\"key\": \"C\", \"text\": \"排水法（作为首选）\"}, {\"key\": \"D\", \"text\": \"向下排空气法并排水\"}]','B','CO2密度比空气大，常用向上排空气法；可溶于水，一般不用排水法作为首选。','选对得分。',1,'pending_review','[inv:q.exp.gas_collect] 骨架；气体收集方法判断模板 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 14:12:06.029','2026-10-18 19:27:38.797'),(8,'judge','（骨架）判断：可以在家中用锌粒和稀硫酸制取氢气并点燃检验。',NULL,'错误','H2为易燃气体，不纯时点燃有爆炸危险；本系统与实验室规范均禁止家用自行制取与点燃。相关内容仅作书面安全判断训练。','判断正确得分；若要求改错，写出“禁止家用、须验纯、仅书面训练”等要点。',1,'pending_review','[inv:q.exp.safety] 骨架；安全判断题；强化禁家用 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 14:12:06.155','2026-10-18 19:27:38.798'),(9,'blank','（骨架）配平：Fe + HCl → FeCl2 + H2（将系数填在各物质前：__ Fe + __ HCl → __ FeCl2 + __ H2）',NULL,'1,2,1,1','原子守恒：Fe+2HCl=FeCl2+H2。','系数全对得分；未配平不得分。',1,'pending_review','[inv:q.eq.balance] 骨架；方程式配平填空模板 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 14:12:06.230','2026-10-18 19:27:38.798'),(10,'single','（骨架）关于甲烷的叙述正确的是？A.分子呈平面正方形  B.分子呈正四面体  C.与Cl2光照只生成一种有机产物  D.不能燃烧','[{\"key\": \"A\", \"text\": \"分子呈平面正方形\"}, {\"key\": \"B\", \"text\": \"分子呈正四面体\"}, {\"key\": \"C\", \"text\": \"与Cl2光照只生成一种有机产物\"}, {\"key\": \"D\", \"text\": \"不能燃烧\"}]','B','甲烷为正四面体；氯代可生成多种氯代产物，C错。','选对得分。',1,'pending_review','[inv:q.organic.methane] 骨架非正式训练题;可充实选项 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 17:06:36.111','2026-10-18 19:27:38.798'),(11,'judge','（骨架）判断：乙烯能使溴水褪色，该反应属于加成反应。',NULL,'正确','CH2=CH2+Br2→CH2BrCH2Br，为加成，溴水褪色。','判断正确得分。',1,'pending_review','[inv:q.organic.ethene] 骨架非正式训练题 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 17:06:36.180','2026-10-18 19:27:38.799'),(12,'blank','（骨架）乙醇催化氧化常用______或______作催化剂并加热，产物乙醛的化学式为______。',NULL,'Cu；Ag；CH3CHO','教材常见Cu或Ag催化加热；2CH3CH2OH+O2→2CH3CHO+2H2O。','催化剂与产物均对得分。',2,'pending_review','[inv:q.organic.ethanol] 骨架非正式训练题 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 17:06:36.298','2026-10-18 19:27:38.800'),(13,'short','（骨架）写出乙酸与乙醇酯化的化学方程式（标明条件与可逆），并说明浓硫酸的作用。',NULL,'CH3COOH+C2H5OH⇌浓硫酸、加热⇌CH3COOC2H5+H2O；浓硫酸作催化剂并吸水（促进平衡）。','酯化可逆；条件与规律为得分点。','方程式+条件+浓硫酸作用要点。',2,'pending_review','[inv:q.organic.ester] 骨架非正式训练题 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 17:06:36.423','2026-10-18 19:27:38.800'),(14,'short','（骨架）写出分子式为C4H10的烷烃的同分异构体结构简式（要求不重复）。',NULL,'CH3CH2CH2CH3；CH3CH(CH3)CH3（正丁烷与异丁烷）','碳链异构两种；检查重复。','两种均写出且不重复得分。',2,'pending_review','[inv:q.organic.isomer] 骨架非正式训练题;基础书写 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 17:06:36.490','2026-10-18 19:27:38.801'),(15,'inference','（骨架）某无机框图：A为淡黄色固体单质，燃烧得气体B；B使品红褪色且加热可恢复。推断A、B（写化学式）并给出关键依据。',NULL,'A为S；B为SO2（依据：淡黄色单质硫；SO2漂白可逆恢复）','颜色+漂白可逆是突破口；需用转化验证。','物质正确+依据要点。',2,'pending_review','[inv:q.inference.block] 骨架非正式训练题;框图模板 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 17:06:36.576','2026-10-18 19:27:38.801'),(16,'inference','（骨架）气体X通入溴水褪色，通入酸性KMnO4也褪色；另有气体Y与溴水混合长时间颜色变化不明显。X、Y更可能分别是乙烯与乙烷还是相反？简述理由。',NULL,'X为乙烯，Y为乙烷；乙烯不饱和可加成/被氧化褪色，乙烷饱和通常不能。','用现象反推饱和性差异。','对应正确+理由。',2,'pending_review','[inv:q.inference.phenomenon] 骨架非正式训练题 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 17:06:36.664','2026-10-18 19:27:38.801'),(17,'multi','（骨架）下列关于烧碱（NaOH）的说法正确的是？','[{\"key\": \"A\", \"text\": \"俗名烧碱、火碱、苛性钠\"}, {\"key\": \"B\", \"text\": \"水溶液显酸性\"}, {\"key\": \"C\", \"text\": \"能与乙酸发生中和反应\"}, {\"key\": \"D\", \"text\": \"固体可敞口长期放置于空气中而无变化\"}]','A,C','NaOH为强碱；易潮解并吸收CO2，不可敞口长期放置。','多选全对得分（或按评分标准给漏选分）。',1,'pending_review','[inv:q.substance.NaOH] 骨架非正式训练题 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 17:06:36.752','2026-10-18 19:27:38.802'),(18,'short','（骨架·综合）简述：①甲烷氯代为何不能写成“只生成CH3Cl”；②Zn-Cu原电池在CuSO4与稀H2SO4中正极反应有何不同；③加热能否作为吸热反应的判据。',NULL,'①可生成多种氯代产物；②CuSO4中正极Cu2+得电子，稀H2SO4中正极H+得电子；③不能，加热是条件不是热效应判据。','覆盖有机取代、原电池电解质差异、能量概念易错点。','三点分别给分。',3,'pending_review','[inv:q.comprehensive.mock] 骨架非正式训练题;综合模拟组 [trainLimit:非正式卷库骨架;禁无约束自动组卷判题;引擎未实现前本备注≠访问控制]',2,2,NULL,NULL,'2026-10-18 17:06:36.890','2026-10-18 19:27:38.803');
