  CONSTRAINT `fk_chem_rxn_sp_sub` FOREIGN KEY (`substance_id`) REFERENCES `chem_substances` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=303 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
