INSERT INTO `chem_train_items` VALUES (1,'train.test.eq.tf.01','test','judge','text','【测试题】化学反应前后原子种类与数目守恒。判断正误。',NULL,'正确','[\"对\", \"T\", \"true\", \"√\"]','【正确答案】正确\n【为什么正确】本题考查化学方程式相关判断。按原子守恒与题干信息，标准答案为「正确」。\n【易错点】配平只改系数不改化学式；条件文字不一定改变方程式本身。',1,1,25,'approved',1,1,0,0,'phase1 test seed; not formal [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 19:41:56.853','2026-10-20 12:22:07.734'),(2,'train.test.eq.tf.02','test','judge','text','【测试题】所有化学反应都是氧化还原反应。判断正误。',NULL,'错误','[\"错\", \"F\", \"false\", \"×\"]','【正确答案】错误\n【为什么正确】本题考查化学方程式相关判断。按原子守恒与题干信息，标准答案为「错误」。\n【易错点】配平只改系数不改化学式；条件文字不一定改变方程式本身。',1,1,25,'approved',1,1,0,0,'phase1 test seed; not formal [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 19:41:57.020','2026-10-20 15:03:04.101'),(4,'train.test.mem.blank.01','test','blank','chem_formula','【测试题】氧元素的元素符号是____。（填符号）',NULL,'O','[]','【正确答案】O\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「O」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'phase1 test seed; not formal [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 19:41:57.303','2026-10-20 12:22:07.876'),(5,'train.test.sub.single.01','test','single','text','【测试题】水的化学式是？','[{\"key\": \"A\", \"text\": \"H2O\"}, {\"key\": \"B\", \"text\": \"HO\"}, {\"key\": \"C\", \"text\": \"H2O2\"}, {\"key\": \"D\", \"text\": \"OH\"}]','A',NULL,'【正确答案】A\n【为什么正确】本题考查物质性质识记/判断。相关记载：「可与活泼金属、氧化物等反应」。标准答案为「A」。\n【易错点】把相似物质的颜色、状态或用途记混。',1,3,128,'approved',1,1,0,0,'phase1 test seed; not formal [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 19:41:57.427','2026-10-20 12:22:07.794'),(6,'train.test.exp.judge.01','test','judge','text','【测试题】危险化学实验可以在家自行操作。判断正误。',NULL,'错误','[\"错\", \"F\", \"false\", \"×\"]','【正确答案】错误\n【为什么正确】本题考查实验相关事实。对照题干与标准答案「错误」判断。\n【易错点】凭感觉忽略气体溶解、加热顺序或安全要点。',1,2,43,'approved',1,1,0,0,'phase1 test seed; not formal [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 19:41:57.625','2026-10-20 11:18:27.192'),(7,'train.test.eq.blank.01','test','blank','chem_formula','【测试题】氯化钠的化学式是____。',NULL,'NaCl','[\"NaCl(s)\"]','【正确答案】NaCl\n【为什么正确】本题考查化学方程式相关判断。按原子守恒与题干信息，标准答案为「NaCl」。\n【易错点】配平只改系数不改化学式；条件文字不一定改变方程式本身。',1,1,25,'approved',1,1,0,0,'phase1 test seed; not formal [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 19:41:58.061','2026-10-20 12:22:07.735'),(8,'train.test.eq.single.02','test','single','text','【测试题】配平化学方程式时必须遵守的是？','[{\"key\": \"A\", \"text\": \"只保证质量相等即可随意改化学式\"}, {\"key\": \"B\", \"text\": \"原子种类与数目守恒\"}, {\"key\": \"C\", \"text\": \"可以改变生成物种类\"}, {\"key\": \"D\", \"text\": \"不需要考虑原子守恒\"}]','B',NULL,'【正确答案】B\n【为什么正确】本题考查化学方程式相关判断。按原子守恒与题干信息，标准答案为「B」。\n【易错点】配平只改系数不改化学式；条件文字不一定改变方程式本身。',1,1,25,'approved',1,1,0,0,'phase1 test seed; not formal [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 19:41:58.419','2026-10-20 12:22:07.736'),(9,'train.test.mem.blank.02','test','blank','chem_formula','【测试题】氢元素的元素符号是____。',NULL,'H','[]','【正确答案】H\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「H」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'phase1 test seed; not formal [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 19:41:58.761','2026-10-20 12:22:07.877'),(10,'train.ai_trial.001.el_sym','test','blank','chem_formula','【AI试运行】氦的元素符号是____。',NULL,'He','[\"HE\", \"he\"]','【正确答案】He\n【为什么正确】本题属于基础记忆。按化学符号/名称/基本事实的标准对应关系，答案为「He」。\n【易错点】元素符号大小写错误；中文名与符号不对应。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.He [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.482','2026-10-20 10:25:32.435'),(11,'train.ai_trial.002.el_sym','test','blank','chem_formula','【AI试运行】锂的元素符号是____。',NULL,'Li','[\"LI\", \"li\"]','【正确答案】Li\n【为什么正确】本题属于基础记忆。按化学符号/名称/基本事实的标准对应关系，答案为「Li」。\n【易错点】元素符号大小写错误；中文名与符号不对应。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.Li [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.483','2026-10-20 11:18:27.183'),(12,'train.ai_trial.003.el_sym','test','blank','chem_formula','【AI试运行】铍的元素符号是____。',NULL,'Be','[\"BE\", \"be\"]','【正确答案】Be\n【为什么正确】本题属于基础记忆。按化学符号/名称/基本事实的标准对应关系，答案为「Be」。\n【易错点】元素符号大小写错误；中文名与符号不对应。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.Be [qa:NEEDS_VERIFICATION] [verify_class:kb_pending] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.484','2026-10-20 11:18:27.204'),(13,'train.ai_trial.004.el_sym','test','blank','chem_formula','【AI试运行】硼的元素符号是____。',NULL,'B','[\"b\"]','【正确答案】B\n【为什么正确】本题属于基础记忆。按化学符号/名称/基本事实的标准对应关系，答案为「B」。\n【易错点】元素符号大小写错误；中文名与符号不对应。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.B [qa:NEEDS_VERIFICATION] [verify_class:kb_pending] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.484','2026-10-20 11:18:27.215'),(14,'train.ai_trial.005.el_sym','test','blank','chem_formula','【AI试运行】碳的元素符号是____。',NULL,'C','[\"c\"]','【正确答案】C\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「C」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.C [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.485','2026-10-20 12:22:07.877'),(15,'train.ai_trial.006.el_sym','test','blank','chem_formula','【AI试运行】氮的元素符号是____。',NULL,'N','[\"n\"]','【正确答案】N\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「N」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.N [qa:NEEDS_VERIFICATION] [verify_class:kb_pending] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.486','2026-10-20 12:22:07.878'),(16,'train.ai_trial.007.el_sym','test','blank','chem_formula','【AI试运行】氟的元素符号是____。',NULL,'F','[\"f\"]','【正确答案】F\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「F」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.F [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.486','2026-10-20 12:22:07.878'),(17,'train.ai_trial.008.el_sym','test','blank','chem_formula','【AI试运行】氖的元素符号是____。',NULL,'Ne','[\"NE\", \"ne\"]','【正确答案】Ne\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「Ne」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.Ne [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.487','2026-10-20 12:22:07.879'),(18,'train.ai_trial.009.el_sym','test','blank','chem_formula','【AI试运行】镁的元素符号是____。',NULL,'Mg','[\"MG\", \"mg\"]','【正确答案】Mg\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「Mg」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.Mg [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.487','2026-10-20 12:22:07.879'),(19,'train.ai_trial.010.el_sym','test','blank','chem_formula','【AI试运行】铝的元素符号是____。',NULL,'Al','[\"AL\", \"al\"]','【正确答案】Al\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「Al」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.Al [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.488','2026-10-20 12:22:07.880'),(20,'train.ai_trial.011.el_sym','test','blank','chem_formula','【AI试运行】硅的元素符号是____。',NULL,'Si','[\"SI\", \"si\"]','【正确答案】Si\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「Si」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.Si [qa:NEEDS_VERIFICATION] [verify_class:kb_pending] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.489','2026-10-20 12:22:07.880'),(21,'train.ai_trial.012.el_sym','test','blank','chem_formula','【AI试运行】磷的元素符号是____。',NULL,'P','[\"p\"]','【正确答案】P\n【为什么正确】结合题干给出的化学事实与判断依据，标准答案为「P」。解析依据题干信息，不外加条件。\n【易错点】凭印象改写知识点；加入题目未给出的条件。',1,11,64,'approved',1,1,0,0,'ai_trial source=el.P [qa:NEEDS_VERIFICATION] [verify_class:kb_pending] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.489','2026-10-20 12:22:07.881'),(22,'train.ai_trial.013.con_j','test','judge','text','【AI试运行】电解质是在水溶液里或熔融状态下能够导电的化合物。判断正误。',NULL,'正确','[\"对\", \"T\", \"true\", \"√\"]','【正确答案】正确\n【为什么正确】电解质是在水溶液里或熔融状态下能够导电的化合物。题干表述与该定义一致，因此正确。导电是因为电离产生自由移动的离子，不是因为有自由电子（那是金属导电）。\n【易错点】把「能导电的单质（如金属、石墨）」也叫做电解质；电解质必须是化合物。',1,5,54,'approved',1,1,0,0,'ai_trial source=concept.electrolyte [qa:NEEDS_VERIFICATION] [verify_class:kb_pending] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.490','2026-10-20 10:25:32.433'),(23,'train.ai_trial.014.con_j','test','judge','text','【AI试运行】蔗糖是电解质。判断正误。',NULL,'错误','[\"错\", \"F\", \"false\", \"×\"]','【正确答案】错误\n【为什么正确】电解质须是在水溶液里或熔融状态下能导电的化合物。蔗糖溶于水后以分子形式存在，不发生电离，溶液中没有自由移动的离子，因此蔗糖是非电解质，不是电解质。题干说「蔗糖是电解质」错误。\n【易错点】看见「化合物」或「能溶于水」就当成电解质；导电的关键是电离出离子，不是单纯溶解。',1,5,55,'approved',1,1,0,0,'ai_trial source=concept.nonelectrolyte [qa:NEEDS_VERIFICATION] [verify_class:kb_pending] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.490','2026-10-20 10:25:32.437'),(24,'train.ai_trial.015.con_j','test','judge','text','【AI试运行】氧化还原反应中，还原剂失电子总数等于氧化剂得电子总数。判断正误。',NULL,'正确','[\"对\", \"T\", \"true\", \"√\"]','【正确答案】正确\n【为什么正确】在氧化还原反应中，还原剂失去电子，氧化剂得到电子。电子不能凭空产生或消失，因此还原剂失电子总数等于氧化剂得电子总数（电子守恒）。配平氧化还原反应时常利用这一关系。\n【易错点】只配平原子个数而忽略电子得失是否相等；把「失电子总数=得电子总数」误记成质量守恒或原子守恒的替代说法。',1,6,113,'approved',1,1,0,0,'ai_trial source=concept.electron_conserve [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.491','2026-10-20 10:25:32.437'),(25,'train.ai_trial.016.rxn_cond','test','judge','text','【AI试运行】反应「4Na + O2 = 2Na2O」在知识库中标注了反应条件。判断正误。',NULL,'正确','[\"对\", \"T\", \"true\", \"√\"]','【考查知识点】化学方程式正误/配平\n【解题突破口】先核对化学式，再核对系数（原子守恒）\n【关键条件】题干给出的反应物、生成物与条件\n【分析过程】以「4Na + O2 = 2Na2O」为参照，对照选项或判断句，确认与标准答案「正确」一致。\n【核心方法】化学式正确 → 原子守恒配平\n【易错点】改化学式凑平；忽略题干限制条件',1,1,25,'approved',1,1,0,0,'ai_trial source=rxn.4Na_O2 [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.491','2026-10-20 12:22:07.736'),(26,'train.ai_trial.017.rxn_redox','test','single','text','【AI试运行】对于反应「4Na + O2 = 2Na2O」，下列哪一项是氧化剂？','[{\"key\": \"A\", \"text\": \"O2\"}, {\"key\": \"B\", \"text\": \"Na\"}, {\"key\": \"C\", \"text\": \"水\"}, {\"key\": \"D\", \"text\": \"氮气\"}]','A','[]','【正确答案】A\n【为什么正确】本题考查氧化剂的判断。氧化剂得到电子、元素化合价降低，自身发生还原反应。对反应「4Na + O2 = 2Na2O」，知识库标注氧化剂为「O2」，与标准答案一致。\n【易错点】氧化剂自身被还原；勿与还原剂混淆。',2,6,103,'approved',1,1,0,0,'ai_trial source=rxn.4Na_O2 [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.492','2026-10-20 11:18:27.235'),(27,'train.ai_trial.018.rxn_cond','test','judge','text','【AI试运行】反应「2Na + O2 = Na2O2」在知识库中标注了反应条件。判断正误。',NULL,'正确','[\"对\", \"T\", \"true\", \"√\"]','【考查知识点】化学方程式正误/配平\n【解题突破口】先核对化学式，再核对系数（原子守恒）\n【关键条件】题干给出的反应物、生成物与条件\n【分析过程】以「2Na + O2 = Na2O2」为参照，对照选项或判断句，确认与标准答案「正确」一致。\n【核心方法】化学式正确 → 原子守恒配平\n【易错点】改化学式凑平；忽略题干限制条件',1,1,25,'approved',1,1,0,0,'ai_trial source=rxn.2Na_O2_heat [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.492','2026-10-20 12:22:07.737'),(28,'train.ai_trial.019.rxn_redox','test','single','text','【AI试运行】对于反应「2Na + O2 = Na2O2」，下列哪一项是氧化剂？','[{\"key\": \"A\", \"text\": \"O2\"}, {\"key\": \"B\", \"text\": \"Na\"}, {\"key\": \"C\", \"text\": \"水\"}, {\"key\": \"D\", \"text\": \"氮气\"}]','A','[]','【正确答案】A\n【为什么正确】本题考查氧化剂的判断。氧化剂得到电子、元素化合价降低，自身发生还原反应。对反应「2Na + O2 = Na2O2」，知识库标注氧化剂为「O2」，与标准答案一致。\n【易错点】氧化剂自身被还原；勿与还原剂混淆。',2,6,103,'approved',1,1,0,0,'ai_trial source=rxn.2Na_O2_heat [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.493','2026-10-20 11:18:27.238'),(29,'train.ai_trial.020.rxn_cond','test','judge','text','【AI试运行】反应「Na2O + H2O = 2NaOH」在知识库中标注了反应条件。判断正误。',NULL,'正确','[\"对\", \"T\", \"true\", \"√\"]','【考查知识点】化学方程式正误/配平\n【解题突破口】先核对化学式，再核对系数（原子守恒）\n【关键条件】题干给出的反应物、生成物与条件\n【分析过程】以「Na2O + H2O = 2NaOH」为参照，对照选项或判断句，确认与标准答案「正确」一致。\n【核心方法】化学式正确 → 原子守恒配平\n【易错点】改化学式凑平；忽略题干限制条件',1,1,25,'approved',1,1,0,0,'ai_trial source=rxn.Na2O_H2O [qa:PASS] [verify_class:none] [trial_access:allow]',NULL,NULL,NULL,NULL,'2026-10-18 20:46:47.493','2026-10-20 12:22:07.737'),(30,'train.ai_trial.021.rxn_nr','test','